WITH payload AS (SELECT $archive_payload$[{"id":"ebd9abbd-5991-5102-9ecd-700940896a3d","document_type":"judgment","category":"judicial","subcategory":"general","title":"زوجية -طلب االنقياد لبيت الزوجية -االختيار بن احلكمن أو قسم اخلبراء للتحكيم -قرار مكتب الصلح بالتفريق بينهما بالعوض الذي سلمه الزوج -احلكم بفسخ النكاح بعوض.","document_number":"3438447","case_number":"3410","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/16","year":"1434","subject":"زوجية -طلب االنقياد لبيت الزوجية -االختيار بن احلكمن أو قسم اخلبراء للتحكيم -قرار مكتب الصلح بالتفريق بينهما بالعوض الذي سلمه الزوج -احلكم بفسخ النكاح بعوض.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك‪ 3438447 :‬تاريخه ‪1434/2/16 :‬هـ‬\n                            ‫رقم الدعوى ‪3410:‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34209112‬تاريخه‪1434/5/7 :‬هـ‬\n\n\n     ‫زوجيــة ‪ -‬طلــب االنقيــاد لبيــت الزوجيــة ‪ -‬االختيــار بــن احلكمــن‬\n     ‫أو قســم اخلبــراء للتحكيــم ‪ -‬قــرار مكتــب الصلــح بالتفريــق بينهمــا‬\n           ‫بالعــوض الــذي ســلمه الــزوج ‪ -‬احلكــم بفســخ النــكاح بعــوض‪.‬‬\n\n\n\n\n     ‫‪ .1‬قــول اهلل تعالــى ( وإن خفتــم شــقاق بينهمــا فابعثــوا حكمـ ًا مــن أهلــه‬\n                                                                  ‫وحكمـ ًا مــن أهلهــا)‬\n     ‫‪ .2‬قــول اهلل تعالى(ومــن آياتــه أن خلــق لكــم مــن أنفســكم أزواجــا‬\n                                 ‫لتســكنوا إليهــا وجعــل بينكــم مــودة ورحمــة)‬\n                       ‫‪ .3‬قول الرسول صلى اهلل عليه وسلم (ال ضرر وال ضرار)‬\n     ‫‪ .4‬قــول الرســول صلــى اهلل عليــه وســلم المــرأة ثابــت بــن قيــس (أترديــن‬\n                          ‫عليــه حديقتــه قالــت نعــم فــردت عليــه فأمــره بفراقهــا)‬\n     ‫‪ .5‬عــن ابــن عبــاس قــال (بعثــت أنــا ومعاويــة حكمــن قــال معمــر‪ :‬بلغنــي‬\n     ‫أن عثمــان بعثهمــا وقــال إن رأيتمــا أن جتمعــا جمعتمــا وإن رأيتمــا أن‬\n                                                                        ‫تفرقــا ففرقــا)‬\n\n\n\n\n     ‫ادعــى زوج علــى زوجتــه يطالبهــا بالرجــوع إلــى بيــت الزوجيــة‪ ،‬صادقــت‬\n     ‫املدعــى عليهــا علــى عقــد النــكاح ورفضــت طلــب املدعــي ألنهــا‬\n\n‫‪93‬‬\n\f‫كرهتــه بســبب ســوء عشــرته وذكــرت أنــه يضربهــا ويشــتمها وال ينفــق‬\n‫عليهــا وطلبــت فســخ نكاحهــا منــه بــا عــوض‪ ،‬رفــض املدعــي فســخ‬\n‫النــكاح‪ ،‬فعرضــت احملكمــة الصلــح بــن الطرفــن فأصــر كل واحــد‬\n‫منهمــا علــى طلبــه فقــررت حتكيــم حكمــن فاختــار املدعيــان قســم‬\n‫اخلبــراء لتحكيمــه بينهمــا‪ ،‬فــورد قــرار مكتــب الصلــح واخلبــراء أنــه‬\n‫بعــد االجتمــاع بالطرفــن ونصحهمــا رأى قســم اخلبــراء التفريــق بينهمــا‬\n‫بعــوض هــو املهــر وقــدره خمســة اآلف ريــال رفــض املدعــى قــرار مكتــب‬\n‫الصلــح ووافقــت عليــه املدعــى عليهــا وأبــرزت عقــد النــكاح وقــرر‬\n‫املدعــي أنــه ســلم املدعــى عليهــا ذهب ـ ًا بقيمــة ثمانيــة عشــر ألــف ريــال‬\n‫واشــترط إذا أرادت املدعــى عليهــا الطــاق أن تعيــد لــه مــا ســلمها مــن‬\n‫قيمــة الذهــب وان تتنــازل لــه عــن حضانــة ابنتــه منهــا‪ ،‬أنكــرت املدعيــة‬\n‫أن قيمــة الذهــب ثمانيــة عشــر ألــف ريــال وقــررت أن قيمتــه خمســة اآلف‬\n‫ريــال فقــط كمــا رفضــت التنــازل عــن ابنتهــا‪ ،‬طلبــت احملكمــة مــن‬\n‫املدعــى البينــة علــى أن قيمــة الذهــب الــذي ســلمه للمدعــى عليهــا كمــا‬\n‫ذكــر واســتعد بإحضــار البينــة وابــرز فواتيــر شــراء ذهــب وبعرضهــا‬\n‫علــى املدعــى عليهــا أنكــرت عالقتهــا بهــا وذكــرت أن زواجهــا باملدعى‬\n‫كان قبــل تاريــخ هــذه الفواتيــر‪ ،‬فســألت احملكمــة املدعــى هــل لديــه‬\n‫زيــادة بينــة فأقــر بأنــه ال بينــة لــه ســوى الفواتيــر التــي قدمهــا‪ ،‬فأفهمتــه‬\n‫احملكمــة بــأن لــه ميــن املدعــى عليهــا علــى أن قيمــة الذهــب ال تتجــاوز‬\n‫خمســة اآلف ريــال فرفــض‪ ،‬واســتعدت املدعــى عليهــا باليمــن وطلبــت‬\n‫احملكمــة منهــا شــيك ًا مصدقـ ًا باســم املدعــى مببلــغ خمســة اآلف ريال‬\n‫فأحضرتــه املدعيــة‪ ،‬وحيــث جــرى حتكيــم حكمــن قــررا الفــراق بــن‬\n‫الطرفــن علــى عــوض قــدره خمســة اآلف ريــال وملــا جــاء يف حديــث امرأة‬\n\n\n                                                                                         ‫‪94‬‬\n\f     ‫ثابــت بــن قيــس حــن ردت عليــه حديقتــه فأمــره النبــي بطالقهــا ونظــرا‬\n     ‫الن اســتمرار احليــاة الزوجيــة مــع وجــود اخلــاف بــن الطرفــن ال يحقــق‬\n     ‫مقاصــد النــكاح لــذا حكمــت احملكمــة بفســخ نــكاح املدعــى عليهــا‬\n     ‫مــن زوجهــا علــى عــوض قــدره خمســة اآلف ريــال وأفهمتهــا بوجــوب‬\n     ‫العــدة عليهــا وأفهمــت املدعــي أن لــه ميــن املدعــى عليهــا علــى نفــي أن‬\n     ‫قيمــة الذهــب تبلــغ ثمانيــة عشــر ألــف ريــال‪ ،‬اعتــرض املدعــي‪ ،‬صــدق‬\n                                              ‫احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )0000‬القاضــي يف احملكمــة العامــة‬\n     ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫العامــة وتاريــخ ‪1432/1/21‬ه املقيــدة وتاريــخ ‪1432/1/21‬ه ـ ففــي يــوم‬\n     ‫الثالثــاء املوافــق ‪1432/4/17‬ه ـ حضــر املدعــي (‪ )0000‬ولــم حتضــر‬\n     ‫املدعــى عليهــا (‪ )0000‬ووردنــا مــن محضــر خصــوم خطــاب التبليــغ رقــم‬\n     ‫(‪ )000‬يف ‪1432/1/23‬ه ـ وقــد تضمــن عــدم تســليمه بســبب عــدم وجــود‬\n     ‫رقــم بطاقــة املدعــى عليهــا‪ .‬ويف يــوم الســبت املوافــق ‪1432/6/11‬ه ـ‬\n     ‫حضــر املدعــي هويتــه ســابق ًا وادعــى علــى احلاضــرة معــه اجلنســية رخصــة‬\n     ‫مطابقــة بطاقتهــا بواســطة مفتشــة النســاء حســب احملضــر املرفــق مبلــف‬\n     ‫الدعــوى قائــا يف دعــواه ‪ :‬إن املدعــى عليهــا زوجتــي مبوجــب وثيقــة عقــد‬\n     ‫زواج وتاريــخ ‪2009/8/5‬م صــادرة مــن مــأذون أنكحــة بكفــر ســليم‬\n     ‫التابــع حملكمــة بنــدر كفــر الــدوار بجمهوريــة مصــر العربيــة علــى مهــر‬\n     ‫قــدره عشــرة آالف جنيــه مصــري مؤخــرة وذهــب مببلــغ ثمانيــة آالف ريال‬\n     ‫ودخلــت بهــا وأجنبــت لــي بنــت (‪ )000‬املولــودة يف تاريــخ ‪2010/6/22‬م‬\n\n‫‪95‬‬\n\f‫ويف شهر ذي احلجة لعام ‪1431‬هـ خرجت من بيتي وسكنت يف سكن‬\n‫خــاص باملمرضــات تابــع والزالــت كذلــك بــدون اذنــي وموافقتــي لــذا‬\n‫أطلــب الزامهــا بالرجــوع إلــى بيتــي والدخــول يف طاعتــي هــذه دعــواي‬\n‫وبعرضهــا علــى املدعــى عليهــا أجابــت قائلــة ‪ :‬مــا ذكــره املدعــي يف‬\n‫دعــواه أننــي زوجتــه مبوجــب العقــد املذكور على املهر املســمى فصحيح‬\n‫وأمــا الذهــب فمبلغــه خمســة اآلف ريــال فقــط وأخــذه منــي بعــد الدخــول‬\n‫وقــد أجنبــت منــه كمــا ذكــر ومــا ذكــره أننــي خرجــت مــن بيتــه فغيــر‬\n‫صحيــح والصحيــح هــو أن ذلــك البيــت الــذي يزعــم أننــي خرجــت منــه‬\n‫هــو بيتــي أنــا وهــو عبــارة عــن شــقة يف حــي (‪ )000‬اســتأجرتها باســمه‬\n‫ودفعــت أجرتهــا وتكلفــة تأثيثهــا وســكناها ســويا وعندمــا قدمــت‬\n‫والدتــي مــن جمهوريــة مصــر للزيــارة ســكنت عنــدي يف الشــقة فخــرج‬\n‫املدعــي مــن الشــقة وســكن مــع والدتــه ووالــده وهجرنــي وابنتــي وبعــد‬\n‫أن ســافرت والدتــي بعــد ثالثــة أشــهر ســلمت الشــقة وانتقلــت للســكن‬\n‫يف ســكن الــذي ذكــره ألننــي أعمــل ممرضــة يف املدينــة الطبيــة‬\n‫املذكــورة وســبب ذلــك أننــي لــم اســتطع أن اســتمر يف ســكن الشــقة‬\n‫لوحــدي وأرفــض احلكــم مبــا طلــب املدعــي ألننــي كرهتــه بســبب ســوء‬\n‫عشــرته فهــو يضربنــي ويشــتمني ويســب الديــن وال يقــوم بالنفقــة الواجبة‬\n‫عليــه ولــم يســتأجر لــي ســكن كمــا أنــه خدعنــي عنــد عقــد النــكاح‬\n‫حيــث ذكــر لــي أنــه طلــق زوجتــه األولــى وتبــن لــي أنــه يكــذب وأنــه‬\n‫الزالــت يف ذمتــه حتــى اآلن لــذا أطلــب فســخ نكاحــي منــه بــا عــوض‬\n‫هكــذا أجابــت وبعــرض ذلــك علــى املدعــي أجــاب قائــا‪ :‬مــا ذكرتــه‬\n‫املدعيــة يف جوابهــا أن الذهــب قيمتــه خمســة آالف ريــال وأننــي أخذتــه‬\n‫منهــا وأنهــا مــن دفــع أجــرة الشــقة وأثاثهــا وأننــي خرجــت مــن الشــقة‬\n\n\n                                                                                 ‫‪96‬‬\n\f     ‫إلــى شــقة والــدي ووالدتــي وأننــي أشــتمها وأضربهــا وال أقــوم بالنفقــة‬\n     ‫وأننــي خدعتهــا بأننــي طلقــت زوجتــي فهــذا كلــه غيــر صحيــح بــل أنــا‬\n     ‫مــن اســتأجر الشــقة وأثثتهــا مــن مالــي اخلــاص وهــي التــي خرجــت منهــا‬\n     ‫إلــى ســكن املمرضــات بــدون أذنــي وال زالــت الشــقة مســتأجرة باســمي‬\n     ‫وعلــى حســابي وأمــا عــن زوجتــي األولــى فقــد أخبرتهــا أنهــا ال زالــت يف‬\n     ‫ذمتــي عنــد عقــد النــكاح والنفقــة الواجبــة علــي قمــت بهــا ولــدي البينــة‬\n     ‫علــى جميــع ذلــك وأرفــض فســخ النــكاح هكــذا أجــاب ثــم جــرى عرض‬\n     ‫الصلــح بــن الطرفــن فأصــر كل منهمــا علــى طلبــه ولقولــه تعالــى (وإن‬\n     ‫خفتــم شــقاق بينهمــا فابعثــوا حكمــا مــن أهلــه وحكمــا مــن أهلهــا) لــذا‬\n     ‫أفهمــت الطرفــن بتعيــن حكمــن مــن أهلهمــا أو إحالتهمــا إلــى قســم‬\n     ‫اخلبــراء للتحكيــم بينهمــا فاختــارا الثانــي لــذا أمــرت بإحالتهمــا إلــى‬\n                                                                       ‫قســم اخلبــراء ‪.‬‬\n     ‫ويف يــوم الســبت املوافق‪1433/09/02‬ه ـ حضــر املدعــي واملدعــى عليهــا‬\n     ‫ووردنــا خطــاب رئيــس احملكمــة رقــم (‪ )000‬وتاريــخ ‪1433/06/09‬ه ـ‬\n     ‫و برفقــه قــرار مكتــب الصلــح بــدون رقــم وتاريــخ ونصــه بعــد املقدمــة‬\n     ‫مــا يلــي ‪ :‬بنــاء علــى خطــاب فضيلــة القاضــي املتعلــق بدعــوى ضــد مــن‬\n     ‫أجــل التحكيــم بينهمــا‪ .‬عليــه نفيــد فضيلتــه أنــه مت االجتمــاع بالزوجــن‬\n     ‫أكثــر مــن مــرة ومناصحتهمــا مــرار ًا وتكــرار ًا وتذكيــر كل واحــد‬\n     ‫منهمــا بــاهلل تعالــى وتــرك الشــقاق وإزالــة النــزاع ونبــذ الفرقــة ولكــن‬\n     ‫الزوجــة أصــرت علــى فســخ النــكاح وأفــادت بإقرارهــا املرفــق بأنهــا ال‬\n     ‫ترغــب يف اســتكمال حياتهــا مــع زوجهــا املدعــى عليــه وبأنهــا تكرهــه‬\n     ‫وتبغضــه وال تطيــق العيــش معــه وأنــه يبخــل ويضــرب وال مانــع لديهــا‬\n     ‫مــن إرجــاع قيمــة الذهــب الــذي ســلمه لهــا وقــدره خمســة آالف ريــال مــع‬\n\n\n‫‪97‬‬\n\f‫أنــه أخــذه منهــا هكــذا أفــادت كمــا أن الــزوج أفــاد بإقــراره املرفــق‬\n‫أنــه متمســك بزوجتــه وأنــه يحبهــا وغيــر مســتعد بطالقهــا حفاظــا علــى‬\n‫ترابــط األســرة وعــدم تفككهــا وبعــد التأمــل يف حالهمــا والنظــر يف‬\n‫واقعهمــا وبقــاء الزوجيــة متعــذر ورجوعهــا ال يخــدم احليــاة الزوجيــة‬\n‫ويتنافــى مــع قولــه تعالــى (ومــن آياتــه أن خلــق لكــم مــن أنفســكم‬\n‫أزواجــا لتســكنوا إليهــا وجعــل بينكــم مــودة ورحمــة) كمــا أن رجــوع‬\n‫الزوجــة وهــي كارهــة يترتــب عليــه ضــرر ولقــول النبــي صلــى اهلل عليــه‬\n‫وســلم (ال ضــرر وال ضــرار) فإننــا نــرى التفريــق بينهمــا بالعــوض الــذي‬\n‫ســلمه الــزوج لهــا يف عقــد النــكاح و قــدره خمســة آالف ريــال هــذا مــا‬\n‫لدينــا و اهلل يحفظكــم ا‪.‬ه ـ وبعرضــه علــى املدعــي أجــاب قائــا‪ :‬أرفض‬\n‫قــرار مكتــب الصلــح و أطلــب إلزامهــا باالنقيــاد معــي هكــذا أجــاب‬\n‫وبعرضــه علــى املدعــى عليهــا أجابــت قائلــة ‪ :‬ال مانــع لــدي أن أعيــد لــه‬\n‫مبلــغ خمســة آالف ريــال هكــذا أجابــت وبطلــب عقــد النــكاح بــن‬\n‫الطرفــن أبــرز املدعــي وثيقــة عقــد زواج صــادرة مــن جمهوريــة مصــر‬\n‫مكتــب تصديقــات البحيــرة وتاريــخ ‪2009/08/06‬م واملتضمــن عقــد‬\n‫النــكاح بــن الطرفــن علــى صــداق قــدره عشــرة آالف وواحــد جنيــه‬\n‫مصــري احلــال منــه واحــد جنيــه واملؤجــل منــه عشــرة آالف جنيــه‪ .‬ا‪.‬ه ـ‬\n‫وقــرر املدعــي بقولــه اجلنيــه الواحــد املذكــور هــو عبــارة عــن رســم يدفــع‬\n‫للحكومــة ولــم أســلم لهــا عشــرة آالف جنيــه ألنهــا مؤخــر وإمنــا ســلمت‬\n‫لهــا ذهبــا بقيمــة ثمانيــة عشــر ألــف ريــال ســعودي وإذا أرادت الطــاق‬\n‫أطلــب أن تعيــد لــي قيمــة ذلــك املهــر وتتنــازل لــي عــن حضانــة بنتــي‬\n‫هكــذا أجــاب وبعــرض ذلــك علــى املدعــى عليهــا أجابــت قائلــة ‪ :‬أمــا‬\n‫الذهــب الــذي ذكــره فقيمتــه خمســة آالف ريــال فقــط وال مانــع لدي من‬\n\n\n                                                                                     ‫‪98‬‬\n\f     ‫ســدادها لــه وأمــا البنــت فأرفــض التنــازل عنها هكذا أجابت وبســؤالها‬\n     ‫عمــا جــاء يف قــرار مكتــب الصلــح مــن أنــه أخــذ الذهــب أجابــت قائلــة‪:‬‬\n     ‫ملــا انتقلــت مــن شــقته إلــى ســكن عملــي تركــت الذهــب ولــم آخــذه‬\n     ‫وكنــت وضعتــه داخــل شــنطة وملــا أحضرهــا لــي لــم أجــد الذهــب فيهــا‬\n     ‫هكــذا أجابــت وبعرضــه علــى املدعــي أجــاب قائــا ‪ :‬لــم آخــذ الذهــب‬\n     ‫هكــذا أجــاب وبعرضــه علــى املدعــى عليهــا أجابــت قائلــة ‪ :‬أطلــب ميينــه‬\n     ‫أنــه لــم يأخــذ الذهــب هكــذا أجابــت وبعرضــه علــى املدعــي اســتعد‬\n     ‫باليمــن فأذنــت لــه وحلــف قائــا ‪ :‬واهلل العظيــم الــذي ال إلــه إال هــو أننــي‬\n     ‫لــم آخــذ ذهــب املدعــى عليهــا الــذي تذكــره بــل هــو معهــا هكــذا حلــف‬\n     ‫وبســؤاله عــن بينتــه أن قيمــة الذهــب املســلم لهــا تبلــغ مــا ذكــره أجــاب‬\n                ‫قائــا ‪ :‬نعــم لــدي بينــة وأطلــب مهلــة إلحضارهــا هكــذا قــرر ‪.‬‬\n     ‫ويف يــوم االثنــن املوافــق ‪1433/11/29‬ه حضــر املدعــي واملدعــى عليهــا‬\n     ‫وبســؤال املدعــي هــل أحضــر بينتــه علــى أن قيمــة الذهــب املســلم لهــا‬\n     ‫تبلــغ مــا ذكــره أبــرز فاتــورة علــى مطبوعــات محــات (‪ )000‬للذهــب‬\n     ‫واملجوهــرات وتاريــخ ‪1431/5/1‬ه ـ واملتضمــن شــراء املدعــي طقم ذهب‬\n     ‫مــن عيــار ‪ 21‬مببلــغ ‪ 6000‬ريــال وأبــرز فاتــورة ثانيــة مــن احملــل نفســه‬\n     ‫برقــم ‪ 15306‬وتاريــخ ‪1430/06/02‬ه ـ واملتضمــن شــراء املدعــي نصــف‬\n     ‫طقــم مــن عيــار ‪ 18‬مببلــغ ‪ 600‬ريــال وفاتــورة ثالثــة مــن احملــل نفســه برقم‬\n     ‫‪ 15311‬وتاريــخ ‪1430/06/05‬ه ـ املتضمــن شــراء املدعــي حلــق ذهبــي‬\n     ‫عيــار ‪ 18‬مببلــغ ‪ 270‬ريــال وفاتــورة رابعــة مــن احملــل نفســه برقــم ‪23304‬‬\n     ‫وتاريــخ ‪1431/05/01‬ه ـ واملتضمــن شــراء املدعــي غوايــش ذهــب مــن‬\n     ‫عيــار ‪ 21‬مببلــغ ‪ 11280‬ريــال وبعــرض ذلــك علــى املدعيــة أجابــت قائلــة‪:‬‬\n     ‫تلــك الفواتيــر ال تخــص الذهــب الــذي اســتلمته وهــي تخــص والدتــه‬\n\n\n‫‪99‬‬\n\f‫ولــم أســتلم منــه شــيئا ويــدل علــى هــذا أن الفاتــورة (‪ )000‬والفاتــورة‬\n‫رقــم (‪ )000‬كلهــا يف عــام ‪1431‬ه بينمــا زواجنــا يف ‪1430/07/10‬ه ـ‬\n‫هكــذا أجابــت وبســؤال املدعــي هــل لديــه بينــة علــى الذهــب الــذي أبــرز‬\n‫فواتيــره أجــاب قائــا ‪ :‬ليــس لــدي بينــة هكــذا أجــاب فأفهمتــه أن لــه‬\n‫ميينهــا علــى نفــي اســتالمها الذهــب وأن قيمــة الذهــب الــذي أعطاهــا ال‬\n‫يتجــاوز خمســة آالف ريــال فرفــض واســتعدت املدعــى عليهــا باليمــن‬\n‫علــى مــا ذكــر لــذا أفهمــت املدعــى عليهــا بإحضــار شــيك مصــدق باســم‬\n‫املدعــي مناولــة رئيــس هــذه احملكمــة بالعــوض الــذي اســتعدت بــه‬\n                               ‫وقــدره خمســة آالف ريــال لــذا رفعــت اجللســة ‪.‬‬\n‫ويف يــوم الســبت املوافــق ‪1434/2/16‬ه ـ حضــر املدعــي واملدعــى‬\n‫عليهــا وقدمــت املدعــى عليهــا الشــيك املصــدق املســحوب علــى مصــرف‬\n‫(‪ )000‬وتاريــخ ‪2012/12/17‬م ممثــل ملبلــغ خمســة آالف ريــال ألمــر‬\n‫رئيــس احملكمــة فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ومــا مت‬\n‫مــن وعظهمــا وتوجيههمــا وإلصــرار كل منهمــا علــى رأيــه ولعمــوم قولــه‬\n‫تعالــى‪ « :‬وإن خفتــم شــقاق بينهمــا فابعثــوا حكم ـ ًا مــن أهلــه وحكم ـ ًا‬\n‫مــن أهلهــا إن يريــدا إصالحـ ًا يوفــق اهلل بينهمــا» وملــا رواه البخــاري عــن‬\n‫ابــن عبــاس رضــي اهلل عنهمــا قــال‪ :‬جــاءت امــرأة ثابــت بــن قيــس بــن‬\n‫شــماس إلــى النبــي صلــى اهلل عليــه وســلم فقالــت‪ :‬يــا رســول اهلل مــا أنقــم‬\n‫علــى ثابــت يف ديــن وال خلــق إال أنــي أخــاف الكفــر يف اإلســام فقــال‬\n‫رســول اهلل صلــى اهلل عليــه وســلم‪ :‬أترديــن عليــه حديقتــه قالــت‪ :‬نعــم‬\n‫فــردت عليــه فأمــره ففارقهــا» وملــا رواه النســائي وعبــد الــرزاق عــن ابــن‬\n‫عبــاس رضــي اهلل عنهمــا قــال‪ :‬بعثــت أنــا ومعاويــة حكمــن قــال معمــر‪:‬‬\n‫بلغنــي أن عثمــان بعثهمــا وقــال إن رأيتمــا أن جتمعــا جمعتمــا وإن رأيتمــا‬\n\n\n                                                                                      ‫‪100‬‬\n\f      ‫أن تفرقــا ففرقــا» ونظــر ًا إلــى أن اســتمرار احليــاة الزوجيــة مــع هــذا‬\n      ‫اخلــاف ال يحقــق مقاصــد النــكاح يف الشــريعة مــن املــودة والرحمــة‬\n      ‫والســكن وتربيــة األوالد والعفــة ونظــر ًا لبقــاء املدعــى عليهــا ناشــز ًا مــع‬\n      ‫طــول املــدة أمــر غيــر محمــود شــرع ًا ومــا قــرره مكتــب قســم اخلبــراء مــن‬\n      ‫التفريــق بينهمــا علــى عــوض قــدره خمســة آالف ريــال وميــن املدعــي علــى‬\n      ‫نفــي أخــذ الذهــب وعــدم بينتــه علــى مــا أنكرتــه املدعــى عليهــا مــن مبلــغ‬\n      ‫الذهــب واســتعدادها بــذل اليمــن علــى ذلــك ورفــض املدعــي قبــول ميينهــا‬\n      ‫لــذا فقــد حكمــت بفســخ نــكاح املدعــى عليهــا مــن زوجهــا املدعــي على‬\n      ‫عــوض قــدره خمســة آالف ريــال وأفهمــت املدعــى عليهــا بــأن عليهــا العدة‬\n      ‫الشــرعية وهــي ثــاث حيــض اعتبــار ًا مــن اليــوم املوافــق ‪1434/2/16‬ه ـ‬\n      ‫وأن ال تتــزوج إال بعــد انقضائهــا واكتســاب احلكــم القطعيــة وأفهمــت‬\n      ‫املدعــي أن لــه ميــن املدعــى عليهــا علــى نفــي أن قيمــة الذهــب تبلــغ ثمانيــة‬\n      ‫عشــر ألــف ريــال متــى طلبهــا وبعــرض ذلــك علــى الطرفــن قــررت املدعى‬\n      ‫عليهــا القناعــة وقــرر املدعــي املعارضــة وطلــب االســتئناف فأجيــب إلــى‬\n      ‫طلبــه وســلم صــورة احلكــم لتقــدمي الئحــة اعتراضــه خــال ثالثــن يومـ ًا‬\n      ‫فــإن مضــت املــدة ولــم يقــدم الئحــة اعتراضــه خاللهــا ســقط حقــه يف‬\n      ‫االعتــراض واكتســب احلكــم القطعيــة وقــررت حفــظ العــوض يف بيــت‬\n      ‫املــال لصالــح املدعــي وبــاهلل التوفيــق‪ ،‬وصلــى اهلل وســلم علــى نبينــا‬\n                   ‫محمــد وعلــى آلــه وصحبــه أجمعــن‪ .‬حــرر يف ‪1434/2/16‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى لتمييــز‬\n      ‫قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف بالرياض‬\n      ‫علــى املعاملــة الــواردة مــن فضيلــة رئيس احملكمــة العامة املســاعد‪........‬‬\n      ‫وتاريــخ ‪1434/4/20‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة القاضي‬\n\n\n‫‪101‬‬\n\f‫باحملكمــة الشــيخ (‪ )00000‬وتاريــخ ‪1434/2/16‬ه ـ اخلــاص بدعــوى‬\n‫(‪( )000‬مصــري اجلنســية ) ضــد (‪( )0000‬مصريــة اجلنســية) بشــأن‬\n‫طلــب املدعــي إلــزام املدعــى عليهــا بالرجــوع لبيتــه واإلنقيــاد لــه‪ ،‬وقــد‬\n‫تضمــن الصــك حكــم فضيلتــه بفســخ نــكاح املدعــى عليهــا مــن املدعــي‬\n‫علــى عــوض قــدره خمســة آالف ريــال ‪ ...‬إلــخ ‪ .‬وبدراســة الصــك وصــورة‬\n‫ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة لــم يظهــر مــا يوجــب‬\n‫االعتــراض ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                                        ‫وســلم ‪.‬‬\n\n\n\n\n                                                                                    ‫‪102‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":93,"source_page_end":102,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3b4193458102aa1283515d9bc576d6a03ba63dbd0521cafac15ef057e64d33ee","normalized_text_hash":"f576c398865dc43785d47c7e25df7030e04f490866ac5aff8e17945036a45735","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p93-3438447"},{"id":"3329f24e-a563-5bcf-9d25-0a0f064b4bd9","document_type":"judgment","category":"judicial","subcategory":"general","title":"انقياد -مطالبة الزوج زوجته االنقياد لبيت الزوجية -مطالبة الزوجة الطاق أو فسخ النكاح مقابل دفع العوض والتنازل عن املؤخر -تعذر الصلح بن الزوجن -طول مدة انفصال الزوجن وأثره -رأى احلكمان التفريق دون عوض -صرف النظر عن دعوى الزوج بطلب انقياد الزوجة لبيت الزوجية -فسخ نكاح الزوجة من زوجها ورجوع املهر املستلم والتنازل عن املؤخر .","document_number":"33450534","case_number":"4132","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/10","year":"1434","subject":"انقياد -مطالبة الزوج زوجته االنقياد لبيت الزوجية -مطالبة الزوجة الطاق أو فسخ النكاح مقابل دفع العوض والتنازل عن املؤخر -تعذر الصلح بن الزوجن -طول مدة انفصال الزوجن وأثره -رأى احلكمان التفريق دون عوض -صرف النظر عن دعوى الزوج بطلب انقياد الزوجة لبيت الزوجية -فسخ نكاح الزوجة من زوجها ورجوع املهر املستلم والتنازل عن املؤخر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33450534 :‬تاريخه‪1433/11/10 :‬هـ‬\n                              ‫رقم الدعوى ‪4132 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 3448060‬تاريخه‪1434/2/26 :‬هـ‬\n\n\n       ‫انقيــاد ‪ -‬مطالبــة الــزوج زوجتــه االنقيــاد لبيــت الزوجيــة‪ -‬مطالبــة‬\n       ‫الزوجــة الطــاق أو فســخ النــكاح مقابــل دفــع العــوض والتنــازل عــن‬\n       ‫املؤخــر‪ -‬تعــذر الصلــح بــن الزوجــن‪ -‬طــول مــدة انفصــال الزوجــن‬\n       ‫وأثــره‪ -‬رأى احلكمــان التفريــق دون عــوض‪ -‬صــرف النظــر عــن دعــوى‬\n       ‫الــزوج بطلــب انقيــاد الزوجــة لبيــت الزوجيــة‪ -‬فســخ نــكاح الزوجــة مــن‬\n                           ‫زوجهــا ورجــوع املهــر املســتلم والتنــازل عــن املؤخــر ‪.‬‬\n\n\n\n                          ‫‪ .1‬قوله تعالى (فإمساك مبعروف أو تسريح بإحسان)‪.‬‬\n       ‫‪ .2‬قولــه تعالــى (وإن خفتــم شــقاق بينهمــا فابعثــوا حكم ـ ًا مــن أهلــه‬\n       ‫وحكم ـ ًا مــن أهلهــا إن يريــدا إصالح ـ ًا يوفــق اهلل بينهمــا إن اهلل كان‬\n                                                                        ‫عليم ـ ًا خبيــرا)‪.‬‬\n       ‫‪ .3‬قولــه صلــى اهلل عليــه وســلم (أميــا امــرأة ســألت الطــاق مــن غيــر مــا‬\n                                                ‫بــأس فحــرام عليهــا رائحــة اجلنــة) ‪.‬‬\n       ‫‪ .4‬عــن ابــن عبــاس رضــي اهلل عنهمــا أن امــرأة ثابــت بــن قيــس أتــت‬\n       ‫النبــي صلــى اهلل عليــه وســلم فقالــت يــا رســول اهلل ثابــت بــن قيــس مــا‬\n       ‫أعيــب عليــه يف خلــق وال ديــن ولكنــي أكــره الكفــر يف اإلســام فقــال‬\n       ‫رســول اهلل صلــى اهلل عليــه وســلم أترديــن عليــه حديقتــه قالــت نعــم قــال‬\n       ‫رســول اهلل صلــى اهلل عليــه وســلم ((اقبــل احلديقــة وطلقهــا تطليقــه))‬\n                                                                          ‫رواه البخــاري‪.‬‬\n\n‫‪103‬‬\n\f‫‪ .5‬قــال ابــن مفلــح يف الفــروع يف أول بــاب اخللــع‪ :‬وقــد اختلــف كالم‬\n‫شــيخنا يقصــد ابــن تيميــة يف وجوبــه يعنــي اخللــع وقــد ألــزم بــه بعــض‬\n                                           ‫حــكام الشــام املقادســة الفضــاء) ‪.‬‬\n‫‪ .6‬قــال الشــيخ محمــد بــن إبراهيــم لعــل اختــاف قــول ابــن تيميــة يف‬\n‫وجوبــه منــزل علــى اختــاف األحــوال وأن قولــه بالوجــوب هــو يف احلالة‬\n‫التــي ييــأس فيهــا مــن طاعتهــا لزوجهــا وانقيادهــا لــه الســنني العديــدة‬\n‫التــي تربــوا فيهــا مفســدة إلزامهــا بحيــث ال يحصــل منــه املقصــود‬\n‫بحــال علــى مفســدة إلــزام الــزوج باملخالعــة الفتــوى رقــم (‪ )2945‬املجلــد‬\n                                                                      ‫(‪)204/10‬‬\n                      ‫‪ .7‬قوله صلى اهلل عليه وسلم ( ال ضرر وال ضرار ) ‪.‬‬\n                                                       ‫‪ .8‬قاعدة الضرر يزال‪.‬‬\n     ‫‪ .9‬املادة (‪ )1/55‬من نظام املرافعات الشرعية ولوائحها التنفيذية‪.‬‬\n\n\n\n\n‫ادعــى املدعــي أن املدعــى عليهــا زوجتــه‪ ،‬وأنــه دخــل بهــا وأجنبــت منــه‬\n‫علــى فــراش الزوجيــة ثالثــة أبنــاء وثــاث بنــات‪ ،‬وأنهــا كانــت تخــرج مــن‬\n‫البيــت دون إذنــه‪ ،‬فنهاهــا عــن ذلــك لكنهــا لــم تنتــه بــل كــررت ذلــك‪،‬‬\n‫كمــا أحلــت عليــه بالعمــل فرفــض‪ ،‬ثــم ذهبــت إلــى أهلهــا قبــل شــهرين‬\n‫مــن تقــدمي الدعــوى وهــي ال تــزال عندهــم‪ ،‬وطلــب إلزامهــا باالنقيــاد‬\n‫لبيــت الزوجيــة‪ ،‬بعــرض دعــوى املدعــي علــى املدعــى عليهــا (املعــرف‬\n‫بهــا مــن قبــل أخيهــا الشــقيق) صادقــت علــى الــزواج واألوالد‪ ،‬وأنكــرت‬\n‫خروجهــا بغيــر إذنــه‪ ،‬وبســؤال املدعــى عليهــا عــن مــدة مكوثها يف منزل‬\n‫أهلهــا وعــن املهــر‪ ،‬قــررت أنهــا خرجــت منــذ ثــاث ســنوات وأن املهــر‬\n\n                                                                                   ‫‪104‬‬\n\f      ‫ثالثــون ألــف ريــال اســتلمت منــه عشــرين ألــف ريــال وعشــرة آالف ريــال‬\n      ‫مؤخــر وأنهــا مســتعدة بافتــداء نفســها مبــا اســتلمته وتتنازل عــن املؤخر‪،‬‬\n      ‫الــزوج يطالــب باالنقيــاد والزوجــة تطلــب الطــاق أو فســخ نكاحهــا‪،‬‬\n      ‫تعــذر اإلصــاح بــن الزوجــن‪ ،‬والزوجــة ترفــض رفض ـ ًا تام ـ ًا الرجــوع‬\n      ‫إلــى زوجهــا وتكرهــه‪ ،‬طــول مــدة انفصــال الزوجــن ويف ذلــك ضــرر‬\n      ‫علــى الزوجــن وخاصــة الزوجــة‪ ،‬والقاعــدة أن الضــرر يــزال‪ ،‬اســتعداد‬\n      ‫الزوجــة ببــذل املهــر املســتلم والتنــازل عــن املؤخــر‪ ،‬املقصــود مــن احليــاة‬\n      ‫الزوجيــة هــو املــودة والســكن والرحمــة وكل هــذه مــن أعمــال القلــوب‬\n      ‫التــي ال ميكــن فيهــا اإلجبــار والقــوة‪ ،‬لــذا مت احلكــم بصــرف النظــر‬\n      ‫عــن طلــب املدعــي انقيــاد الزوجــة لبيــت الزوجيــة‪ ،‬واحلكــم بفســخ‬\n      ‫نــكاح الزوجــة مــن زوجهــا املدعــى عليــه علــى أن ترجــع املهــر املســتلم‬\n      ‫لزوجهــا وقــدره عشــرون ألــف ريــال وتنازلهــا عــن مؤخــر الصــداق وقــدره‬\n      ‫عشــرة آالف ريــال‪ ،‬جــرى إفهــام الزوجــة ووليهــا احلاضــر معهــا أال تتــزوج‬\n      ‫حتــى يكتســب احلكــم القطعيــة بعــد أن تعتــد ثــاث حيــض مــن تاريــخ‬\n      ‫الفســخ‪ ،‬يعتبــر هــذا احلكــم يف حــق املدعــى عليــه حضوريـاً‪ ،‬بعــد رفــع‬\n      ‫احلكــم حملكمــة االســتئناف لوحــظ أن فضيلــة القاضــي لــم يطلــب مــن‬\n      ‫املدعــى عليهــا إحضــار العــوض احملكــوم بــه للــزوج عوضـ ًا عــن الفســخ‬\n      ‫وإيداعــه يف بيــت املــال احتــراز ًا مــن املماطلــة يف إحضــاره‪ ،‬بعــرض ذلــك‬\n      ‫علــى املدعــى عليهــا أبــرزت الشــيك املصــريف برقــم ‪ .....‬يف‪ ....‬مببلــغ‬\n      ‫عشــرين ألــف ريــال ألمــر املدعــي‪ ،‬اســتلم املدعــي الشــيك املذكور‪،‬بعــد‬\n                           ‫رفــع احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه‪.‬‬\n\n\n\n\n‫‪105‬‬\n\f‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‬\n‫فلــدي أنــا ‪ ...................‬بنــاء علــى املعاملــة احملالــة برقــم ‪ 3582‬يف‬\n‫‪1430/5/21‬ه ـ واملقيــدة برقــم ‪3013892‬يف ‪1430/5/21‬ه ـ ففــي‬\n‫يــوم الثالثــاء ‪1432/7/5‬ه ـ حضــر املدعــي ‪ ...........‬فلســطيني اجلنســية‬\n‫مبوجــب اإلقامــة رقــم(‪ ).............‬وزوجتــه ‪ .............‬أردنيــة اجلنســية‬\n‫مبوجــب اإلقامــة رقــم(‪ )...............‬واملعــرف بهــا مــن قبــل أخيهــا الشــقيق‬\n‫‪ ...............‬أردنــي اجلنســية مبوجــب اإلقامــة رقــم (‪ )...............‬فجــرى‬\n‫ســؤال املدعــي ‪ ........‬عــن دعــواه فقــال إن هــذه احلاضــرة زوجتــي عقــدت‬\n‫عليهــا بتاريــخ ‪1403/12/4‬ه ـ ودخلــت بهــا وأجنبــت منــي علــى فــراش‬\n‫الزوجيــة ثالثــة أبنــاء وثــاث بنــات وقبــل تقــدمي الدعــوى لــدى احملكمــة‬\n‫بســنة كانــت تخــرج بــدون إذنــي فنهيتهــا عــن ذلــك لكنهــا لــم تنتــه بــل‬\n‫كــررت ذلــك كمــا أحلــت علــي بالعمــل فرفضــت ذلــك ثــم ذهبــت إلــى‬\n‫أهلهــا قبــل شــهرين مــن تقــدمي الدعــوى وإلــى اآلن هــي عنــد أهلهــا لــذا‬\n‫أطلــب إلزامهــا باالنقيــاد لبيــت الزوجيــة هــذه دعــواي ‪ ،‬وبســؤال املدعيــة‬\n‫عمــا جــاء يف دعــوى املدعــي أجابــت قائلــة مــا ذكــره املدعــي مــن الــزواج‬\n‫واألوالد هــذا صحيــح وأمــا خروجــي بــدون إذنــه فهــو غيــر صحيــح وأمــا‬\n‫طلــب العمــل فقــد عملــت بإذنــه وموافقتــه اخلطيــة يف النــدوة العامليــة‬\n‫للشــباب اإلســامي ملــدة ســنة ثــم قــدم املدعــي اســتقالتي بنفســه وأمــا‬\n‫ذهابــي إلــى منــزل أهلــي فإننــي قبــل أربــع ســنوات بــدأت أكرهــه حتــى‬\n‫أصبحــت أكرهــه كرهـ ًا شــديد ًا ال أســتطيع أداء حقــه علــي لــذا أطلــب‬\n‫رد دعــواه وإلزامــه بخلعــي وأنــا مســتعدة بدفــع العــوض هكــذا أجابــت‬\n\n                                                                                       ‫‪106‬‬\n\f      ‫فجــرى نصــح الزوجــن وتذكيرهمــا بحقوقهمــا ومعروفهمــا والعشــرة‬\n      ‫التــي بينهمــا ووجــود األوالد الســتة وتذكيــر الزوجــة بقولــه صلــى اهلل‬\n      ‫عليــه وســلم (أميــا امــرأة ســألت الطــاق مــن غيــر مــا بــأس فحــرام عليهــا‬\n      ‫رائحــة اجلنــة) فأصــرت الزوجــة علــى رأيهــا وقالــت إننــي ال أســتطيع‬\n      ‫العــودة إليــه وقــد حاولــت عــدة مــرات لكننــي ال أســتطيع العيــش معــه‬\n      ‫ثــم جــرى نصــح الــزوج وتذكيــره بقولــه تعالــى (فإمســاك مبعــروف أو‬\n      ‫تســريح بإحســان) فقــال إننــي ال أرى ســبب ًا للطــاق وأخشــى مــن اإلثــم يف‬\n      ‫ذلــك ورفــض الطــاق فجــرى ســؤال املدعــي عمــا جــاء يف جــواب املدعيــة‬\n      ‫فقــال إنــه غيــر صحيــح وأنــا أرفــض خـلعـه ــا والـصـحـي ــح أنـن ــي أذنــت لـه ــا‬\n      ‫بالعـ ــمل يف ال ـنـ ــدوة الـعـالـمي ــة وكذلــك جلنــة التنميــة يف حــي الروضــة‬\n      ‫فأصبحــت تــداوم دوامــن صباحــي ومســائي ممــا ترتــب عليــه ضيــاع‬\n      ‫ال ــمنزل واألوالد فـطل ــبت منهــا تــرك العمــل فرفضــت فقدمت اســتقالتها‬\n      ‫بنفســي لكنهــا أصبحــت تذهــب للعمــل وتخــرج بــدون إذنــي هكــذا‬\n      ‫أجــاب ولقولــه تعالــى (وإن خفتــم شــقاق بينهمــا فابعثــوا حكم ـ ًا مــن‬\n      ‫أهلــه وحكم ـ ًا مــن أهلهــا إن يريــدا إصالح ـ ًا يوفــق اهلل بينهمــا إن اهلل‬\n      ‫كان عليمـ ًا خبيــرا) طلبــت منهمــا اختيــار حكمــن فاختــارت الزوجــة‬\n      ‫هيئــة النظــر يف احملكمــة أمــا الــزوج فقــال أطلــب مهلــه إلــى يــوم‬\n      ‫األربعــاء ‪1432/7/13‬ه ـ للبحــث عــن حكــم ‪ ،‬ويف هــذا اليــوم الثالثــاء‬\n      ‫‪1432/8/25‬ه ـ حضــر الطرفــان واملعــرف هــذا وقــد وردنــا جــواب هيئــة‬\n      ‫النظــر بالقــرار رقــم ‪ 268‬يف ‪1432/8/16‬ه ـ وقــد وقــع عليــه عضــو هيئــة‬\n      ‫النظــر ســليمان الشــرمي وأمــا حكــم الــزوج ‪............‬فقــرر مبــا نصــه‬\n      ‫((تنازلــت رســمي ًا عــن التحكيــم وســلمت التنــازل بيــد ناظــر القضيــة‬\n      ‫وقــد حضــر لدينــا قبــل اجللســة هــذا احلكــم وهــو موظــف باحملكمــة‬\n\n\n‫‪107‬‬\n\f‫وقــدم اعتــذاره املتضمــن أن عضــو الهيئــة لــم يأخــذ برأيــه أ‪.‬هــ)) وقــد‬\n‫تضمــن القــرار املذكــور مــا نصــه (( لــذا تــرى الهيئــة أن االنفصــال مــن‬\n‫الزوجــن هــو األولــى بــدون عــوض حيــث أن عمــر الــزواج أكثــر مــن‬\n‫خمــس وعشــرين ســنة ومقــدار الصــداق ثالثــون ألــف ريــال ولــم يتــم دفــع‬\n‫ســوى عشــرين ألــف ريــال )) ‪ ،‬وألنــه لــم يردنــا جــواب مــن حكــم الــزوج‬\n‫فقــد طلبــت مــن الطرفــن احلضــور جميع ـ ًا عنــد حكــم الــزوج األول‬\n‫‪ ...........‬فاســتعدا بذلــك ‪ ،‬ويف يــوم الثالثــاء ‪1432/10/29‬ه ـ حضــرت‬\n‫املدعيــة واملعــرف بهــا ولــم يحضــر زوجهــا خصمهــا فجــرى ســؤالها هــل‬\n‫حضــرت لــدى حكــم الــزوج فقالــت ال لــم أحضــر ولــم يتصــل بي خصمي‬\n‫ليحــدد لــي املوعــد هكــذا أجابــت فســألتها كــم كان املهــر بينكمــا‬\n‫فقالــت عشــرون ألــف ريــال وأضافــت ال مــا نــع لــدي مــن إرجــاع هــذا‬\n‫املبلــغ ألجــل أن أفتــدي نفســي منــه ويفســخ نكاحــي منــه هكــذا قــررت‬\n‫فســألتها منــذ متــى وأنــت يف منــزل أهلــك فقالــت منــذ ثــاث ســنوات‬\n‫هكــذا أجابــت ‪ ،‬ويف هــذا اليــوم الثالثــاء ‪1432/12/26‬ه ـ حضــرت‬\n‫املدعيــة برفقــة والدهــا املعــرف بهــا ‪ ..............‬أردنــي اجلنســية مبوجــب‬\n‫اإلقامــة رقــم ………‪ .‬ولــم يحضــر املدعــى عليــه وجــرى ســؤال الزوجــة‬\n‫هــل اتصــل عليهــا زوجهــا للحضــور إلــى حكــم الــزوج فقالــت ال هكــذا‬\n‫أجابــت كمــا قــررت املدعيــة أنهــا مســتعدة ببــذل العــوض لتفتــدي‬\n‫نفســها هكــذا قــررت وأضافــت إننــي أطالــب بفســخ نكاحــي ألنــي‬\n‫أخشــى أال أقــوم بحقــه وأكرهــه فســألتها كــم املهــر قالــت ثالثــون‬\n‫ألــف ريــال عشــرون ألــف ريــال اســتلمتها وعشــرة آالف ريــال مؤخــر‬\n‫صــداق وإننــي أتنــازل عنــه إذا فســخ نكاحــي ‪ ،‬فبنــاء علــى مــا تقــدم مــن‬\n‫الدعــوى واإلجابــة وألن الــزوج يطالــب باالنقيــاد والزوجــة تطلــب الطــاق‬\n\n\n                                                                                     ‫‪108‬‬\n\f      ‫أو فســخ نكاحهــا وألنــه تعــذر اإلصــاح بــن الزوجــن خاصــة أنــه مت‬\n      ‫اختيــار أكثــر مــن حكــم وألن الزوجــن منفصــان قـب ــل أك ــثر مــن‬\n      ‫أرب ــع سن ــوات حـس ــب م ــا ج ــاء يف الدعوى واإلجابة وألن الزوجة ترفض‬\n      ‫رفض ـ ًا تام ـ ًا الرجــوع إلــى زوجهــا وتكرهــه ويف صحيــح البخــاري (عــن‬\n      ‫ابــن عبــاس رضــي اهلل عنهمــا أن امــرأة ثابــت بــن قيــس أتــت النبــي صلــى‬\n      ‫اهلل عليــه وســلم فقالــت يــا رســول اهلل ثابــت بــن قيــس مــا أعيــب عليــه‬\n      ‫يف خلــق وال ديــن ولكنــي أكــره الكفــر يف اإلســام فقــال رســول اهلل‬\n      ‫صلــى اهلل عليــه وســلم أترديــن عليــه حديقتــه قالــت نعــم قــال رســول اهلل‬\n      ‫صلــى اهلل عليــه وســلم ((أقبــل احلديقــة وطلقهــا تطليقــه)) وقــد ذكــر‬\n      ‫أهــل العلــم أن قــول امــرأة ثابــت أكــره الكفــر يف اإلســام خشــية مــن‬\n      ‫كفــران العشــير إذا جلســت معــه أو أن يحملهــا بغضهــا إلــى الكفــر‬\n      ‫حتــى ينفســخ نكاحهــا منــه) وقــد قــال ابــن مفلــح يف الفــروع يف أول بــاب‬\n      ‫اخللــع وقــد اختلــف كالم شــيخنا يقصــد ابــن تيميــه يف وجوبــه يعنــي‬\n      ‫اخللــع وقــد ألــزم بــه بعــض حــكام الشــام املقادســة الفضــاء) قال الشــيخ‬\n      ‫محمــد بــن إبراهيــم لعــل اختــاف قــول ابــن تيميــه يف وجوبــه منــزل علــى‬\n      ‫اختــاف األحــوال وأن قولــه بالوجــوب هــو يف احلالــة التــي ييــأس فيهــا مــن‬\n      ‫طاعتــه لزوجهــا وانقيادهــا لــه الســنني العديــدة التــي تربــوا فيهــا مفســدة‬\n      ‫إلزامهــا بحيــث ال يحصــل منــه املقصــود بحــال علــى مفســدة إلــزام الــزوج‬\n      ‫باملخالعــة الفتــوى رقــم (‪ 2945‬املجلــد ‪ ، )204/10‬ونظــر ًا لطــول مــدة‬\n      ‫انفصــال الزوجــن ويف ذلــك ضــرر علــى الزوجــن وخاصــة الزوجــة‬\n      ‫ولقولــه صلــى اهلل عليــه وســلم ( ال ضــرر وال ضــرار ) وألن القاعــدة أن‬\n      ‫الضــرر يــزال وألن الزوجــة اســتعدت ببــذل املهــر املســتلم والتنــازل عــن‬\n      ‫املؤخــر وألن الــزوج وافــق علــى مبــدأ اخللــع مقابــل دفع أربعمائة وخمســن‬\n\n\n‫‪109‬‬\n\f‫ألــف ريــال كمــا يف جلســة يــوم الثالثــاء ‪1432/12/26‬ه ـ وألن النبــي‬\n‫صلــى اهلل عليــه وســلم ملــا اشــتكت إليــه امــرأة ثابــت لــم يرددهــا بــل‬\n‫أمــره بالطــاق ملــا وافقــت علــى إرجــاع احلديقــة وألن املقصــود مــن احليــاة‬\n‫الزوجيــة هــو املــودة والســكن والرحمــة وكل هــذه مــن أعمــال القلــوب‬\n‫ـاء علــى املــادة (‪ )1/55‬مــن نظــام‬‫التــي ال ميكــن فيهــا اإلجبــار والقــوة وبنـ ً‬\n‫املرافعــات الشــرعية جلميــع مــا ســبق فقــد صرفــت أو ًال النظــر عــن دعــوى‬\n‫الــزوج بطلبــه انقيــاد الزوجــة لبيــت الزوجيــة ‪ ،‬ثاني ـ ًا فســخت نــكاح‬\n‫الزوجــة ‪ .....................‬مــن زوجهــا ‪ ...................‬بتاريــخ ‪1432/12/26‬ه ـ‬\n‫علــى أن ترجــع املهــر املســتلم لزوجهــا وقــدره عشــرون ألــف ريــال وتنازلهــا‬\n‫عــن مؤخــر الصــداق وقــدره عشــرة آالف ريــال وبــه حكمــت وأفهمــت‬\n‫الزوجــة ووليهــا احلاضــر أال تتــزوج حتــى يكتســب احلكــم القطعيــة‬\n‫بعــد أن تعتــد ثــاث حيــض مــن تاريــخ الفســخ وهــذا احلكــم حضــوري‬\n‫يف حــق املدعــى عليــه خاضــع لتع ــليمات االســتئناف وكانــت ســاعة‬\n‫الـنـط ــق بال ــحكم الســاعة الواحــدة والربــع وبــاهلل ال ــتوفيق وصلــى‬\n‫اهلل وســلم علــى نبينــا محمــد وعـل ــى آلــه وصحبــه أجمعــن ‪ ،‬ح ـ ـ ــرر يف‬\n                                                                   ‫‪1433/11/10‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فقــد‬\n‫وردتنــا املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية برقــم‬\n‫‪ 33/2101460‬وتاريــخ ‪1434/1/26‬ه ـ املرفــق بهــا قــرار دائــرة األحــوال‬\n‫الشــخصية األولــى رقــم ‪349667‬وتاريــخ ‪1434/1/12‬ه ـ املتضمــن‬\n‫(وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق‬\n‫املعاملــة لوحــظ مــا يلــي لــم جنــد أن فضيلــة القاضــي حــال توجــه احلكــم‬\n‫بالفســخ طلــب مــن املدعــى عليهــا إحضــار العــوض احملكــوم بــه للــزوج‬\n\n\n                                                                                         ‫‪110‬‬\n\f      ‫عوضـ ًا عــن الفســخ وأجــرى مــا تقتضيــه التعليمــات مــن إيداعــه يف بيــت‬\n      ‫املــال حتــت اإليجــاب الشــرعي احتــراز ًا مــن املماطلــة يف إحضــاره مــع‬\n      ‫صــدور احلكــم بالفســخ فعلــى فضيلتــه مالحظــة مــا أشــير إليــه وإحلــاق‬\n      ‫مــا يجــد يف الصــك وضبطــه وســجله ومــن ثــم إعــادة املعاملــة إلكمــال‬\n      ‫الزمهــا واهلل املوفــق) أعضــاء الدائــرة قاضــي اســتئناف ‪ ..............‬توقيعــه‬\n      ‫وختمــه قاضــي اســتئناف ‪ ................‬توقيعــه وختمــه رئيــس الدائــرة‬\n      ‫‪ ...................‬توقيعــه وختمــه ومــع تقديــري ملشــايخي الفضــاء فقــد‬\n      ‫حضــر الطرفــان يف هــذا اليــوم األحــد ‪1434/2/3‬ه ـ الســاعة الواحــدة‬\n      ‫والربــع ومعهمــا ابنهمــا املعــرف ‪ ............‬فلســطيني اجلنســية باإلقامــة رقم‬\n      ‫‪ ............‬وجــرى عــرض املالحظــة عليهمــا فقالــت الزوجــة إننــي مســتعدة‬\n      ‫بذلــك وأبــرزت الشــيك املصــريف املســحوب علــى البنــك الفرنســي برقــم‬\n      ‫‪ 849608‬يف ‪1434/2/3‬ه ـ مببلــغ عشــرين ألــف ريــال ألمــر ‪............‬‬\n      ‫وأمــا الــزوج فقــال إننــي لــم أقنــع باحلكــم أصــا فأفهمــت الــزوج بأنــه إذا‬\n      ‫اكتســب احلكــم القطعيــة ولــم يســتلم مبلغــه فســيتم إيداعــه يف بيــت‬\n      ‫مــال احملكمــة ولــه املطالبــة بــه متــى شــاء ولــن يتوقــف فســخها علــى‬\n      ‫اســتالمه أمــا املؤخــر وقــدره عشــرة آالف ريــال فقــد تنازلــت عنــه الزوجــة‬\n      ‫وبــاهلل احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‬\n      ‫لــدي أنــا ‪ ..............‬القاضــي القائــم بعمــل املكتــب القضائي العاشــر ويف‬\n      ‫يــوم الســبت حضــر ‪ ................‬فلســطيني اجلنســية مبوجــب اإلقامــة رقــم‬\n      ‫‪ ..................‬وقــد طلــب اســتالم الشــيك املصــريف رقــم‪ 1/849608‬يف‬\n      ‫‪1434/2/3‬ه ـ املســحوب علــى البنــك الســعودي ‪ .......‬باســمه وقــد جــرى‬\n      ‫ال مــن ‪.................‬‬\n                             ‫تســليمه الشــيك املذكــور أعــاه بحضــور وشــهادة ك ً‬\n      ‫و‪ ....................‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n\n\n‫‪111‬‬\n\f                                    ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف‪1434/4/6‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة دائ ــرة األحــوال‬\n‫الشــخصية األولــى يف محكمــة االســتئناف باملنطقــة الشــرقية‬\n‫علــى املعاملــة املقيــدة باحملكمــة برقــم ‪/34/337549‬ش‪ 1‬وتاريــخ‬\n‫‪1434/2/10‬ه ـ الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بالدمــام‬\n‫برقــم ‪ 34225855‬وتاريــخ ‪1434/2/5‬ه ـ املرفــق بهــا الصــك الصــادر من‬\n‫فضيل ــة القاضــي بهــا الشــيخ ‪ .....................‬املســجل برقــم ‪33450534‬‬\n‫وتاريــخ ‪1433/11/10‬ه ـ اخلــاص بدعــوى‪ ......................../‬فلســطيني‬\n‫اجلنســية ضــد‪ ........................./‬أردنيــة اجلنســية يف قضيــة خــاف‬\n‫زوجــي‪ .‬املالحــظ عليــه بقــرارات الدائــرة رقــم ‪/489‬ش‪/1‬ب وتاريــخ‬\n‫‪1433/6/3‬ه ـ ورقــم ‪ 33410676‬وتاريــخ ‪1433/9/13‬ه ـ ورقــم‬\n‫‪ 349667‬وتاريــخ ‪1434/1/12‬ه ـ وباإلطــاع علــى مــا أجــراه فضيلــة‬\n‫القاضــي جوابـ ًا علــى قــرار الدائــرة األخيــر قررنــا املصادقــة علــى احلكم‬\n‫بعــد اإلجــراء األخيــر‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                  ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/2/ 25‬هــ‪.‬‬\n\n\n\n\n                                                                                    ‫‪112‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":103,"source_page_end":112,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2c213d32e5825e9cd541a4c88780b09b08c6511b4e58f0cf3aca11d06774f44c","normalized_text_hash":"b5a799b7be00e51a2b2ef829fe866e746683817965728dc23d5b945f1c5fe777","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p103-33450534"},{"id":"c19ad732-aa58-50f0-b051-1010b238917f","document_type":"judgment","category":"judicial","subcategory":"general","title":"زوجية -طلب االنقياد لبيت الزوجية -بعث حكمن ورد قرارهما بفسخ النكاح دون عوض -حلف مين على عدم سوء العشرة - حلفت بيمينها على عدم اإلنفاق -احلكم فسخ النكاح دون عوض","document_number":"33422612","case_number":"3317221","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/10/10","year":"1434","subject":"زوجية -طلب االنقياد لبيت الزوجية -بعث حكمن ورد قرارهما بفسخ النكاح دون عوض -حلف مين على عدم سوء العشرة - حلفت بيمينها على عدم اإلنفاق -احلكم فسخ النكاح دون عوض","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33422612 :‬تاريخه ‪1433/10/10 :‬هـ‬\n                            ‫رقم الدعوى ‪3317221:‬‬\n            ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                    ‫‪ 34204358‬تاريخه‪1434/5/4 :‬هـ‬\n\n\n        ‫زوجيــة ‪ -‬طلــب االنقيــاد لبيــت الزوجيــة ‪ -‬بعــث حكمــن ورد قرارهمــا‬\n        ‫بفســخ النــكاح دون عــوض ‪ -‬حلــف ميــن علــى عــدم ســوء العشــرة ‪-‬‬\n        ‫حلفــت بيمينهــا علــى عــدم اإلنفــاق ‪ -‬احلكــم فســخ النــكاح دون عــوض‬\n                                                                ‫‪ -‬صــدق احلكــم‪.‬‬\n\n\n\n\n        ‫‪ .1‬قضــى النبــي عليــه الصــاة والســام أن اليمــن علــى املدعــى عليــه‬\n                                                                          ‫رواه البخــاري‬\n        ‫‪ .2‬قــول الرســول صلــى اهلل عليــه وســلم (ال ضــرر وال ضــرار) رواه أبــو‬\n                                                                                     ‫داوود‬\n        ‫‪ .3‬وحلديــث (البينــة علــى املدعــي واليمــن علــى املدعــى عليــه) رواه‬\n                                                                               ‫الترمــذي‬\n        ‫‪ .4‬قــال أبــو عيســى عنــد أهــل العلــم مــن أصحــاب النبــي صلــى اهلل عليــه‬\n             ‫وســلم وغيرهــم أن البينــة علــى املدعــي واليمــن علــى املدعــى عليــه ‪.‬‬\n        ‫‪ .5‬قــال ابــن القيــم (كل عيــب ينفــر الــزوج اآلخــر منــه وال يحصــل بــه‬\n                           ‫مقصــود النــكاح يوجــب اخليــار‪ ،‬وأنــه أولــى مــن البيــع)‬\n                                                   ‫‪ .6‬قال يف اإلنصاف (ما هو ببعيد)‬\n\n\n\n\n‫‪113‬‬\n\f‫ادعــى زوج علــى زوجتــه يطالبهــا باالنقيــاد إلــى بيــت الزوجيــة‪ ،‬أقــرت‬\n‫املدعــى عليهــا بالنــكاح وذكــرت أن املدعــي هــو مــن أخرجها من البيت‬\n‫وطلــب مــن والدهــا احلضــور ألخذهــا وذكرت انه ســيئ العشــرة‪،‬حاولت‬\n‫احملكمــة اإلصــاح ثــم قــررت حتكيــم حكمــن بينهمــا‪ ،‬ســعى‬\n‫احلكمــان يف اإلصــاح بــا جــدوى ويــروا فســخ النــكاح بــا عــوض إذا‬\n‫ثبــت لــدى احملكمــة أي مســوغ مــن مســوغات فســخ النــكاح‪ ،‬قــررت‬\n‫املدعــى عليهــا أنهــا تطلــب فســخ نكاحهــا مــن املدعــي وأنهــا ال تطيــق‬\n‫العيــش معــه لعــدم إنفاقــه وســوء عشــرته‪ ،‬فطلبــت احملكمــة منهــا البينة‬\n‫علــى ذلــك‪ ،‬فقــررت أنــه ال بينــة لهــا‪ ،‬ثــم طلبــت احملكمــة مــن املدعــي‬\n‫البينــة علــى اإلنفــاق فقــرر أنــه ال بينــة لــه‪ ،‬عرضــت احملكمــة اليمــن‬\n‫علــى املدعــى عليهــا علــى عــدم نفقــة املدعــى فاســتعدت بذلــك وحلفــت‪،‬‬\n‫ملــا دفعــت بــه املدعــى عليهــا مــن عــدم اإلنفــاق وأنــكار املدعــي ذلــك‬\n‫بــدون بينــة وألن األصــل عــدم اإلنفــاق وقــد حلفــت املدعــى عليهــا علــى‬\n‫عــدم اإلنفــاق وحلديــث (البينــة علــى املدعــى واليمــن علــى مــن انكــر)‬\n‫ولقولــه صلــى اهلل عليــه وســلم (ال ضــرر وال ضــرار) وألن الضــرر يف‬\n‫الشــريعة مرفــوع فقــد أذنــت احملكمــة للمدعــي عليهــا بفســخ نكاحهــا‬\n‫مــن زوجهــا املدعــى ففســخت نكاحهــا فحكمــت احملكمــة بذلــك‬\n‫وأفهمــت املدعــى عليهــا بــأن عليهــا العــدة الشــرعية‪ ،‬اعتــرض املدعــى‪،‬‬\n                                                             ‫صــدق احلكــم ‪.‬‬\n\n\n\n\n                                                                                  ‫‪114‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )000‬القاضــي يف احملكمــة العامــة‬\n      ‫مبحافظة جدة وبناء على املعاملة احملالة لنا من فضيلة رئيس احملكمة‬\n      ‫العامــة بجــدة املســاعد وتاريــخ ‪1433/1/5‬ه ـ املقيــدة باحملكمــة‬\n      ‫وتاريــخ ‪1433/01/05‬ه ففــي يــوم الثالثــاء املوافق‪1433/10/10‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 12 : 00‬وفيهــا حضــر (‪ )0000‬وأدعــى علــى‬\n      ‫احلاضــرة معــه (‪ )000‬قائــا ‪ :‬إن املدعــى عليهــا زوجتــي ‪ ،‬عقــدت بهــا يف‬\n      ‫‪1431/5/12‬ه ـ علــى مهــر قــدره عشــرون ألــف ريــال مســلم بالكامــل‬\n      ‫مبوجــب العقــد الصــادر مــن احملكمــة اجلزئيــة للضمــان واألنكحــة ‪7‬‬\n      ‫يف ‪1431/5/21‬ه ـ ودخلــت بهــا يف ‪1431/8/8‬ه ـ وقــد رزقــت منهــا بابــن‬\n      ‫مــن مواليــد ‪1432/6/29‬ه ـ ‪ ،‬وقــد خرجــت مــن بيتــي يف ‪1432/1/9‬ه ـ‬\n      ‫وكانــت حامــا ‪ ،‬أطلــب انقيــاد زوجتــي لــي وإلزامهــا بالرجــوع لبيتــي‪.‬‬\n      ‫هــذه دعــواي ‪ .‬ثــم أبــرز املدعــي عقــد النــكاح املشــار إليــه ‪ ،‬ومت إرفــاق‬\n      ‫نســخة منــه باملعاملــة‪ ،‬وبعــرض ذلــك علــى املدعــى عليهــا قالــت ‪ :‬إن‬\n      ‫مــا ذكــره املدعــي مــن العقــد واملهــر والدخــول واإلجنــاب واخلــروج‬\n      ‫فصحيــح‪ ،‬ولكــن لــم أســتلم مــن املهــر املســمى يف العقــد ســوى ســبعة‬\n      ‫عشــر ألــف ريــال ‪ ،‬وال أذكــر تاريــخ خروجــي مــن بيتــه بالتحديــد ‪،‬‬\n      ‫وســبب خروجــي ســوء العشــرة واخلالفــات املتكــررة بيننــا ‪ ،‬وقد طردني‬\n      ‫مــن البيــت ‪ ،‬وهــو مــن طلــب مــن والــدي احلضــور ألخــذي ‪ .‬وقــد وردتنــا‬\n      ‫املعاملــة مــن قســم الصلــح بخطــاب رئيســها تاريــخ ‪1433/9/4‬ه ـ مرفــق‬\n      ‫بــه محضــر اللجنــة املتضمــن حضــر الطرفــان وبعــد ســماع مالديهمــا‬\n      ‫ومحــاوالت اإلصــاح املتكــررة بينهمــا لعــدة جلســات فقــد جــرى طلــب‬\n\n‫‪115‬‬\n\f‫احلكمــن فأحضــرت الزوجــة حكمــا وهــو علــي (‪ )000‬واحضــر الــزوج‬\n‫حكمــا وهــو (‪ )000‬وقــد ســعى بينهمــا احلكمــان يف اإلصــاح وتقريــب‬\n‫وجهــات النظــر ولكــن أفــادا بــأن مســاعي الصلــح قــد فشــلت وتوقفــت‬\n‫عــن اشــتراط املــرأة أن يكــون ســكنها يف وأن اجلمــع يســتحيل يف‬\n‫ظــل هــذه اخلالفــات والفــراق أولــى وحيــث االمــر كذلــك وملــا ذكرتــه‬\n‫املــرأة أن الــزوج مقصــر يف نفقتهــا ويســيء عشــرتها وقــد ضربهــا وأنــه‬\n‫ال مانــع لديهــا مــن الرجــوع إليــه بشــرط أن يفتــح لهــا بيتــا يف جــدة وذلــك‬\n‫ألن أخالقــه تســوء إذا بعــد بهــا عــن أهلهــا فأذكــر الــزوج جميــع ذلــك‬\n‫ورفــض شــرطها إال أن يكــون يف مكــة فلــم توافــق وأضافــت بــأن الــزوج‬\n‫قــد أخــل بشــرط ورد يف عقــد النــكاح وهــو أن ميتنــع عــن التدخــن فأقــر‬\n‫الــزوج بذلــك الشــرط وصحتــه وأنــه لــم يقتــرب مــن التدخــن وال صحــة‬\n‫إلخاللــه بذلــك الشــرط وأنــه يريــد رجوعهــا إليــه وقــد حضــر والــد الــزوج‬\n‫وهــو وكيلــه ومــن قــام بتحريــر عقــد النــكاح بالوكالــة وقــد أقــر بــأن‬\n‫الشــرطني يف العقــد كانــا مــن إشــتراطات الزوجــة بــأن ميتنــع الــزوج عــن‬\n‫التدخــن وأن تســافر معــه إذا ســافر وال مينعــه ات مــن أن تكــون معــه‬\n‫وهــذا هــو تفســير الشــرط ومت إعتــراض الــزوج علــى ذلــك وقال إن شــرط‬\n‫اإلقامــة معــي هــو شــرطي أنــا وليــس شــرطها ورجــع والــده عــن كالمــه‬\n‫الســابق وقــال كان ذلــك الشــرط شــرط إبنــي أساســا وأن مــن تلفــظ بــه‬\n‫وقــت حتريــر عقــد النــكاح هــو والــد الزوجــة وهــذا هــو مــا دعانــي إلــى‬\n‫قــول مــا ســبق وحيــث االمــر كذلــك ولرفــض الزوجة الرجوع اال بشــرط‬\n‫وإلصــرار الــزوج علــى الرجــوع بــدون شــرط ولتعــذر اإلصــاح فإننــا نــرى‬\n‫ان حالــه اجلمــع بــن الزوجــن وان يفســخ نــكاح املــرآة بــدون عــوض إن‬\n‫أثبتــت إخــال الــزوج بشــرط العقــد إبتــداء أو أثبتــت لــدى فضيلتكــم أيــا‬\n\n\n                                                                                       ‫‪116‬‬\n\f      ‫مــن مســوغات فســخ النــكاح وهــذا مــا نــراه والــراي لفضيلتكــم اه ـ ‪.‬‬\n      ‫وقــرر املدعــي قائــا ‪ :‬لقــد أقلعــت عــن التدخــن منــذ حوالــي عــام‬\n      ‫ونصــف‪ .‬وبعــرض ذلــك علــى املدعــى عليهــا قالــت ‪ :‬حــن تركتــه كان‬\n      ‫يدخــن ‪ ،‬وأطلــب إحالتــه إلــى الطبيــب الشــرعي لتحقــق مــن أنــه الزال‬\n      ‫علــى ذلــك ‪ ،‬واملدعــي يســيء عشــرتي ومقصــر يف حقوقــي الزوجيــة‪،‬‬\n      ‫وقــد ضربنــي عــدة مــرات وال ينفــق علــي ‪ ،‬وال أطيــق العيــش معــه وأطلــب‬\n      ‫فســخ نكاحــي منــه ‪ .‬وبعــرض ذلــك علــى املدعــي قــال ‪ :‬أن مــا ذكرتــه‬\n      ‫املدعيــة فغيــر صحيــح ‪ ،‬وأنــا أنفــق عليهــا مبعــدل يومــي قــدره ألــف إلــى‬\n      ‫ألــف وخمســمائة ريــال مينــي‪ .‬وبطلــب البينــة مــن املدعــى عليهــا علــى ســوء‬\n      ‫العشــرة والضــرب فقالــت ‪ :‬ليــس لــدي بينــة ‪ .‬وبطلــب البينــة مــن املدعــي‬\n      ‫علــى األنفــاق قــال ‪ :‬كنــت أنفــق عليهــا وهــي يف بيتــي وليــس لــدي بينــة‬\n      ‫علــى ذلــك ‪ .‬وبعــرض اليمــن علــى املدعــي علــى حســن العشــرة وعــدم‬\n      ‫ضــرب املدعــى عليهــا أســتعد لذلــك ثــم حلــف قائــا ‪ :‬واهلل العظيــم‬\n      ‫الــذي ال إلــه إال هــو اننــي أحســن عشــرة املدعــى عليهــا ولــم أضربهــا‬\n      ‫قــط ‪ .‬هكــذا حلــف ‪ .‬وبعــرض اليمــن علــى املدعــى عليهــا علــى عــدم‬\n      ‫إنفــاق املدعــي اســتعدت لذلــك ثــم حلفــت قائلــة ‪ :‬واهلل العظيــم الــذي‬\n      ‫ال إلــه إال هــو أن املدعــي مقصــر يف النفقــة بحيــث ال ينفــق النفقــة‬\n      ‫التــي تكفــي بحســب حالــه وحالــي ‪ ،‬ومــا يدفعــه مــن نفقــة ال تكفــي‬\n      ‫حلاجاتــي الضروريــة واألساســية ‪ .‬هكــذا حلفــت ‪ .‬فبنــاء علــى مــا تقــدم‬\n      ‫مــن الدعــوى واإلجابــة ‪ ،‬وبنــاء علــى مــا قــرره أعضــاء جلنــة الصلــح ‪،‬‬\n      ‫وبنــاء علــى مــا دفعــت بــه املدعــى عليهــا مــن عــدم النفقــة وأنكــر‬\n      ‫املدعــي ذلــك دون بينــة ‪ ،‬وألن االصــل اإلنفــاق ‪ ،‬وقــد حلفــت املدعــى‬\n      ‫عليهــا علــى تقصيــر املدعــي يف النفقــة وعــدم كفايتهــا ‪ ،‬وحلديــث (أن‬\n\n\n‫‪117‬‬\n\f‫النبــي صلــى اهلل عليــه وســلم قضــى أن اليمــن علــى املدعــى عليــه) رواه‬\n‫البخــاري ‪ ،‬وحلديــث (البينــة علــى املدعــي واليمــن علــى املدعــى عليــه)‬\n‫رواه الترمــذي‪ ،‬قــال أبــو عيســى ‪ :‬العمــل عنــد أهــل العلــم مــن أصحــاب‬\n‫النبــي صلــى اهلل عليــه وســلم وغيرهــم أن البينــة علــى املدعــي واليمــن‬\n‫علــى املدعــى عليــه‪ ،‬ولقولــه صلــى اهلل عليــه وســلم ( ال ضــرر و ال ضــرار)‬\n‫رواه أبــو داوود وصححــه احلاكــم وألن الضــرر يف الشــريعة مرفــوع‪،‬‬\n‫وملــا ذكــره ابــن القيــم ونصــه ‪( :‬كل عيــب ينفــر الــزوج اآلخــر منــه‪،‬‬\n‫وال يحصــل بــه مقصــود النــكاح‪ ،‬يوجــب اخليــار‪ ،‬وأنــه أولــى مــن البيــع)‪.‬‬\n‫وقــال يف اإلنصــاف ‪ :‬مــا هــو ببعيــد‪ .‬لذلــك كلــه‪ ،‬فقــد أذنــت للمدعــى‬\n‫عليهــا يف فســخ نكاحهــا مــن زوجهــا فقالــت ‪ :‬فســخت نكاحــي مــن‬\n‫زوجــي‪ .‬لــذا فقــد حكمــت بفســخ نــكاح املدعــى عليهــا مــن زوجهــا‬\n‫هــذا اليــوم الثالثــاء املوافــق ‪1433/10/10‬ه ـ ‪ .‬وبــه حكمــت ‪ .‬وبعــرض‬\n‫احلكــم قــررت املدعــى عليهــا القناعــة ‪ ،‬وقــرر املدعــي االعتــراض ‪،‬‬\n‫وجــرى تســليمه نســخة مــن احلكــم وأفهمــت املدعــى عليهــا بــأن عليهــا‬\n‫العــدة الشــرعية حســب حالهــا بعــد اكتســاب احلكــم القطعيــة ‪ ،‬وأن‬\n‫احتســاب العــدة مــن تاريــخ احلكــم‪ ،‬وإفهــام املدعــي بأنــه بعــد اكتســاب‬\n‫احلكــم القطعيــة فــإن زوجتــه قــد بانــت منــه بينونــة صغــرى ال حتــل‬\n‫لــه إال بعقــد ومهــر جديديــن ‪ .‬وإفهامــه بــأن لــه حــق االعتــراض عليــه‬\n‫خــال ثالثــن يومــا مــن تاريــخ اســتالمه للحكــم ‪ ،‬وإال ســقط حقــه‬\n‫يف االعتــراض واكتســب احلكــم القطعيــة ‪ .‬وأقفلــت اجللســة الســاعة‬\n‫(‪ ، )2:30‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                  ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1433/10/10‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )0000‬القاضــي باحملكمــة العامــة‬\n\n\n                                                                                   ‫‪118‬‬\n\f      ‫بجــدة الشــيخ (‪ )0000‬ففــي يــوم الســبت املوافــق ‪1434/3/14‬ه ـ‬\n      ‫أفتتحــت اجللســة الســاعة ‪ 11 : 15‬وقــد عــادت املعاملــة مــن محكمــة‬\n      ‫االســتئناف بخطــاب رئيســها رقــم ‪ 34296985‬وتاريــخ ‪1434/2/23‬ه ـ‬\n      ‫وبالقــرار وتاريــخ ‪1434/2/16‬ه ـ واملتضمــن مــا يلــي وبدراســة الصــك‬\n      ‫وصــورة ضبطــه والئحــة االعتراضيــة تقــرر باألكثريــة إعادتهــا لفضيلــة‬\n      ‫حاكمهــا ملالحظــة ‪ :‬أن املدعــى عليهــا هــي التي تطالب بفســخ نكاحها‬\n      ‫وأدعــت بعــدم النفقــة والضــرب ولــم يطلــب اثبــات ذلــك وال ســوء عشــرة‬\n      ‫املدعــي واحلكــم بفســخ نكاحهــا واحلــال مــا ذكــر بــدون عــوض محــل‬\n      ‫نظــر فعلــى فضيلتــه اعــادة النظــر والتأمــل واجــراء الــازم أ‪ .‬ه ـ وعليــه‬\n      ‫أجيــب أصحــاب الفضيلــة أن ســوء العشــرة والضــرب لــم تســتطع املدعــى‬\n      ‫عليهــا اثباتــه ‪ ،‬وذلــك بقولهــا ( ليــس لــدي بينــه ) وحلــف املدعــي علــى‬\n      ‫إنــكار ذلــك ولكنهــا ادعــت عــدم النفقــة ‪ ،‬ولــم يقــم املدعــي البينة على‬\n      ‫النفقة ‪ ،‬وحلفت املدعى عليها على أن املدعي مقصر يف النفقة ‪ ،‬وألن‬\n      ‫مــا ذكــر يف التســبيب كاف يف إيقــاع فســخ النــكاح ال ســيما وهــو رأي‬\n      ‫احلكمــان ورأي أعضــاء جلنــة اإلصــاح وعليــه فلــم يظهــر لــي خــاف‬\n      ‫مــا أجريتــه ‪ ،‬وقــررت إحلــاق ذلــك علــى صــك احلكــم وســجله وإعــادة‬\n      ‫املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم بعــد اإلجــراء األخيــر‬\n      ‫وأقفلــت اجللســة الســاعة (‪ )11:25‬وبــاهلل التوفيــق وصلــى اهلل وســلم‬\n        ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/3/14‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )000‬القاضــي باحملكمــة العامــة‬\n      ‫بجــدة يف يــوم االثنــن املوافــق ‪1434/5/20‬ه ـ أفتتحــت اجللســة الســاعة‬\n      ‫(‪ )2:15‬وقــد عــادت املعاملــة مــن محكمــة االســتئناف بخطــاب رئيســها‬\n      ‫رقــم ‪ 34506764‬وتاريــخ ‪1434/5/11‬ه ــوبالقرار وتاريخ ‪1434/5/4‬هـ‬\n\n\n‫‪119‬‬\n\f‫واملتضمــن مــا يلــي وبدراســة الصــك وصــورة ضبطــه والئحــة االعتراضية‬\n‫تقــررت املوافقــة علــى احلكــم بعــد االجــراء االيضــاح االخيــر وحتــى ال‬\n‫يخفــى جــرى أثباتــه وأمــرت بأحلاقــه بصكــه وســجله وأقفلــت اجللســة‬\n‫الســاعة (‪ )2:20‬وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد‬\n‫وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/5/20‬ه ـ احلمــد هلل وحده وبعد‬\n‫فلــدي أنــا (‪ )0000‬القاضــي يف احملكمــة العامــة مبحافظــة جــدة القائــم‬\n‫بعمــل القاضــي أثنــاء فترة إجــازة ففي يوم الثالثاء املوافق‪1434/07/04‬‬\n‫ه ـ افتتحــت اجللســة الســاعة ‪ 8 : 45‬وقــد عــادت املعاملــة مــن محكمــة‬\n‫األســتئناف بخطــاب رئيســها رقــم وتاريــخ ‪1434/6/27‬ه ـ وبالقــرار رقــم‬\n‫وتاريــخ ‪1434/6/13‬ه ـ ومضمونــه مــا يلــي ‪ :‬وبدراســة املعاملــة تقــرر‬\n‫مــا يلــي ‪ :‬أو ًال ‪ :‬رفــض االلتمــاس لعــدم وجــود مــا يبــرر ه ‪ .‬ثاني ـ ًا ‪ :‬بنــاء‬\n‫علــى املــادة ‪ 3/195‬مــن الالئحــة التنفيذيــة لنظــام املرافعــات الشــرعية‬\n‫فيــزود حاكــم القضيــة بصــورة مــن هــذا القــرار إلكمــال الــازم‬\n‫وحتــى ال يخفــى جــرى أثباتــه وأقفلــت اجللســة الســاعة ‪ 8 : 55‬وبــاهلل‬\n‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر‬\n‫يف ‪1434/7/4‬ه ـ احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد‬\n‫نحــن قضــاة الدائــرة الثانيــة لألحــوال الشــخصية واألوقــاف والوصايــا‬\n‫والقصــار وبيــوت املــال يف محكمــة االســتئناف جــرى منــا االطــاع‬\n‫علــى الصــك الصــادر مــن فضيلــة الشــيخ‪ )000( /‬القاضــي باحملكمــة‬\n‫العامــة املــؤرخ يف ‪1433/10/10‬ه ـ املتضمــن دعــوى‪ )0000( /‬يف قضيــة‬\n‫زوجيــة ‪ ،‬وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة تقررت‬\n‫املوافقــة علــى احلكــم بعــد االيضــاح االخيــر واهلل املوفــق وصلــى اهلل‬\n                                    ‫علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم‪.‬‬\n\n\n                                                                                          ‫‪120‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":113,"source_page_end":120,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d9a8c239eda225bb0dc852832f57f7696a0ad4ab13f073c21a4b5fcb5fe8cfbe","normalized_text_hash":"ab42abc2a653e5d467cecf2a63cfe8484a03f5eda496b5e99cce474f7f70a7ef","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p113-33422612"},{"id":"2464ec61-2eff-5d21-af80-d2f9cf50efad","document_type":"judgment","category":"judicial","subcategory":"general","title":"انقياد -مطالبة زوج مطلقته الرجوع لبيت الزوجية -إقرار الزوج بالطاق ومراجعة الزوجة خال فترة العدة -رفض الزوجة الرجوع النتهاء عدتها وعدم املراجعة -شهادة شاهدين مع الزوج -حلف الزوجة اليمن على عدم استرجاع زوجها لها -رجحان بيانات الزوجة -تناقض أقوال الزوج والشهود -احلكم بثبوت طاق املدعى عليها دون عوض وخروجها من العدة دون مراجعة .","document_number":"34291518","case_number":"3421986","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة املساعد رفق كتابه و","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/8","year":"1434","subject":"انقياد -مطالبة زوج مطلقته الرجوع لبيت الزوجية -إقرار الزوج بالطاق ومراجعة الزوجة خال فترة العدة -رفض الزوجة الرجوع النتهاء عدتها وعدم املراجعة -شهادة شاهدين مع الزوج -حلف الزوجة اليمن على عدم استرجاع زوجها لها -رجحان بيانات الزوجة -تناقض أقوال الزوج والشهود -احلكم بثبوت طاق املدعى عليها دون عوض وخروجها من العدة دون مراجعة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34291518 :‬تاريخه ‪1434/8/8 :‬هـ‬\n                           ‫رقم الدعوى ‪3421986:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34341214‬تاريخه‪1434/10/26 :‬هـ‬\n\n\n      ‫انقيــاد ‪ -‬مطالبــة زوج مطلقتــه الرجــوع لبيــت الزوجيــة ‪ -‬إقــرار الــزوج‬\n      ‫بالطــاق ومراجعــة الزوجــة خــال فتــرة العــدة ‪ -‬رفض الزوجــة الرجوع‬\n      ‫النتهــاء عدتهــا وعــدم املراجعــة ‪ -‬شــهادة شــاهدين مــع الــزوج ‪ -‬حلــف‬\n      ‫الزوجــة اليمــن علــى عــدم اســترجاع زوجهــا لهــا ‪ -‬رجحــان بيانــات‬\n      ‫الزوجــة ‪ -‬تناقــض أقــوال الــزوج والشــهود ‪ -‬احلكــم بثبــوت طــاق‬\n             ‫املدعــى عليهــا دون عــوض وخروجهــا مــن العــدة دون مراجعــة ‪.‬‬\n\n\n\n      ‫‪-1‬قــول ابــن قدامــة يف املغنــي (املــرأة إذا ادعــت انقضــاء عدتهــا يف مــدة‬\n                                 ‫ميكــن انقضاؤهــا فيهــا قبــل قولهــا) ‪563/10‬‬\n      ‫‪ -2‬قــول الزركشــي (إذا قــال ارجتعتــك فقالــت انقضــت عدتــي قبــل‬\n                                ‫رجعتــك فالقــول قولهــا مــع ميينهــا)‪452/5‬‬\n      ‫‪-3‬املــادة ‪ 55‬مــن نظــام املرافعــات الشــرعية الفقــرة ‪1‬و‪ 2‬مــن اللوائــح‬\n                                                                        ‫التنفيذيــة ‪.‬‬\n\n\n\n      ‫أقــام زوج دعــوى يطالــب زوجتــه بالرجــوع إلــى بيــت الزوجيــة وذكــر‬\n      ‫فيهــا أنــه طلقهــا ثــم راجعهــا وهــي يف العــدة‪ ،‬أقــرت املدعــى عليهــا بــأن‬\n      ‫املدعــي كان زوجــا لهــا وأنــه طلقهــا وأنكــرت أنــه راجعهــا واســتدلت‬\n\n\n‫‪121‬‬\n\f‫علــى عــدم املراجعــة بــأن املدعــي حضــر إليهــا بعــد خروجهــا مــن العــدة‬\n‫ومعــه مــأذون أنكحــة ليعقــد عليهــا بعقــد آخــر ولســوء التفاهــم بينهمــا‬\n‫لــم يتــم العقــد وهــذا يــدل علــى عــدم صحــة مراجعتــه كمــا اســتدلت‬\n‫بفتــوى ســماحة مفتــي اململكــة علــى أن للمدعــي العــودة بعقــد جديــد‬\n‫وبشــروط لــذا رفضــت الرجــوع إليــه وتطلــب إثبــات طالقهــا‪ ،‬قــررت‬\n‫احملكمــة الكتابــة ملــأذون األنكحــة املذكــور يف جــواب املدعى عليها‬\n‫لإلفــادة عمــا لديــه فــورد جوابــه بــأن املدعــي طلــب منــه الذهــاب إلــى بيت‬\n‫املدعــى عليهــا لعقــد النــكاح وأن وليهــا رفــض العقــد حتــى صــدور فتــوى‬\n‫مــن ســماحة املفتــي ولــم يتــم عقــد النــكاح‪ ،‬أنكــر املدعــي مــا ذكــره‬\n‫مــأذون األنكحــة‪ ،‬ثــم طلــب املدعــي األذن لــه بإحضــار شــهود علــى‬\n‫املراجعــة فأحضرهــم وبعــد ســماعها وإثباتهــا ترجــح لــدى احملكمــة‬\n‫قــوة بينــات املدعــى عليهــا التــي تثبــت وقــوع الطــاق وخروجهــا مــن‬\n‫عدتهــا دون اســترجاع املدعــى لهــا‪ ،‬فطلبــت احملكمــة مــن املدعــى‬\n‫عليهــا اليمــن علــى عــدم اســترجاع املدعــى لهــا أثنــاء عدتهــا فاســتعدت‬\n‫بذلــك ثــم حلفــت‪ ،‬بالبنــاء علــى مــا تقــدم وملــا قــرره الفقهــاء مــن أن املــرأة‬\n‫إذا ادعــت انقضــاء عدتهــا يف مــدة ميكــن انقضاؤهــا فيهــا قبــل قولهــا‪،‬‬\n‫لــذا لــم يثبــت لــدى احملكمــة مراجعــة املدعــي للمدعــى عليهــا أثنــاء‬\n‫عدتهــا وأثبتــت طــاق املدعــي للمدعــى عليهــا وأنهــا خرجــت مــن العــدة‬\n‫دون مراجعــة وأفهــم املدعــي بأنــه ليــس لــه الرجــوع علــى املدعــى عليهــا‬\n‫إال بعقــد ومهــر جديديــن وبرضاهــا وإن عليــه مراجعــة األحــوال املدنيــة‬\n‫إلســقاطها مــن كــرت العائلــة‪ ،‬اعتــرض املدعــي‪ ،‬صــدق احلكــم مــن‬\n                                                               ‫محكمــة االســتئناف‪.‬‬\n\n\n\n                                                                                           ‫‪122‬‬\n\f      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي‬\n      ‫هــذا اليــوم الثالثــاء املوافــق ‪1434/4/23‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫العاشــرة صباحـ ًا وفيهــا حضــر املدعــي ‪ ........‬وحضــرت حلضــوره املدعــى‬\n      ‫عليهــا ‪ ........‬ســعودية املعــرف بهــا مــن قبــل والدهــا احلاضــر ‪ ........‬ســعودي‬\n      ‫بالســجل رقــم ‪ ........‬وادعــى املدعــي بقولــه إن املدعــى عليهــا زوجتــي‬\n      ‫عقــدت عليهــا ودخلــت بهــا مبوجــب عقــد الــزواج يف ‪1429/10/2‬ه ـ‬\n      ‫وأجنبــت منــي ذكــر ًا مــن مواليــد ‪1432/2/21‬ه ـ وقــد طلقتهــا طلقــة‬\n      ‫واحــدة يف ‪1433/4/23‬ه ـ ومنــذ طالقــي لهــا ذهبــت لبيــت أهلهــا وقــد‬\n      ‫راجعتهــا قبــل خروجهــا مــن عدتهــا بشــهادة شــهود أي أننــي راجعتهــا‬\n      ‫بعــد شــهر ونصــف مــن طالقــي لهــا واملدعــى عليهــا ال تــزال يف بيــت‬\n      ‫والدهــا وترفــض العــودة لبيــت الزوجيــة لــذا أطلــب إلزامهــا بالرجــوع‬\n      ‫لبيــت الزوجيــة علم ـ ًا أننــي أحضــرت عاقــد األنكحــة يف رمضــان‬\n      ‫‪1433/09/23‬ه ـ ليعقــد لــي علــى املدعــى عليهــا عقــد ًا ثانــي ولكــن‬\n      ‫والدهــا اشــترط مهــر ًا قــدره ثمانــون ألــف ريــال هــذه دعــواي وبعــرض‬\n      ‫دعــوى املدعــي علــى املدعــى عليهــا أجابــت بقولهــا مــا ذكــره املدعــى‬\n      ‫عليــه مــن أنــه تزوجنــي وعقــد علـ ّـي ودخــل بــي مبوجــب عقــد النــكاح‬\n      ‫املذكــور أعــاه وأجنبــت منــه ذكــر ًا ثــم طلقنــي يف ‪1433/4/23‬ه ـ‬\n      ‫فهــذا كلــه صحيــح وأمــا مراجعتــه لــي وأنــا يف عدتــي فغيــر صحيــح‬\n      ‫وشــهوده علــى املراجعــة شــهادة غيــر صحيحــة وال أقبــل بشــهادتهم وذلــك‬\n      ‫إلقــراره أنــه أحضــر عاقــد األنكحــة ليعقــد زواجــي بــه عقــد ًا آخــر بعــد‬\n      ‫طالقــه لــي ولكــن لســوء التفاهــم بيننــا لــم يتــم العقــد وكان ذلــك يف‬\n\n‫‪123‬‬\n\f‫‪1433/09/23‬ه ـ ويــدل أيض ـ ًا علــى عــدم صحــة مراجعتــه لــي مــا جــاء‬\n‫بفتــوى مفتــي عــام اململكــة ســماحة الشــيخ عبدالعزيــز آل الشــيخ والتــي‬\n‫نصــت علــى أن لــه العــودة لــي بعقــد جديــد بشــروطه والفتــوى محــررة‬\n‫يف ‪1433/10/18‬ه ـ وعاقــد األنكحــة اســمه ‪ ........‬والــذي أفــاد أنــه‬\n‫كاتــب عــدل بحائــل ونطلــب مخاطبتــه وعليــه فــا ميكــن لــي الرجــوع‬\n‫إليــه ومصــرة علــى إثبــات طالقــي منــه هكــذا أجابــت وملخاطبــة‬\n‫كاتــب العــدل عاقــد األنكحــة عمــا لديــه مــن شــهادة وعــن صحــة‬\n‫مــا أفــاد بــه املدعــي واملدعــى عليهــا رفعــت اجللســة ليــوم األحــد املوافــق‬\n‫‪1434/07/30‬ه ـ الســاعة التاســعة صباحـاً‪ ،‬واهلل املوفــق ‪،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/4/23‬ه ـ‬\n                                 ‫الســاعة العاشــرة وأربعــون دقيقــة صباح ـ ًا ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد؛ ففــي‬\n‫هــذا اليــوم األحــد املوافــق ‪1434/7/30‬ه ـ افتتحــت اجللســة الســاعة‬\n‫التاســعة والنصــف صباحــا وفيهــا حضــر املدعــي واملدعــى عليهــا‬\n‫واملعــرف لهــا وملخاطبتنــا مــأذون األنكحــة يف ‪1434/4/29‬ه لإلفــادة‬\n‫الواقعــة املذكــورة بدعــوى املدعــي وإجابــة املدعــى عليهــا فــوردت‬\n‫اإلجابــة يف ‪1434/5/4‬ه ـ ومضمونهــا (أفيدكــم بأنــي يف عصــر يــوم‬\n‫‪1433/9/23‬ه ـ تلقيــت اتصــال مــن املدعــي‪ /‬طلــب فيــه منــي أن أقــوم‬\n‫بعقــد نــكاح لــه بعــد صــاة التراويــح مــن نفــس ذلــك اليــوم فوافقتــه‬\n‫علــى ذلــك مــن غيــر أن أعلــم عــن أي تفاصيــل؛ وحــن حضــرت إلــى منــزل‬\n‫والــد الزوجــة ‪ ........‬الواقــع يف حــي ‪ ......‬مبدينــة حائــل تبــن لــي أن هنــاك‬\n‫خالفــات بــن الــزوج ووالــد الزوجــة؛ ورفــض والــد الزوجــة القيــام بعقــد‬\n‫النــكاح لكونهــم جميعــا يف نفــس ظهــر ذلــك اليــوم حضــروا ملركــز‬\n\n\n                                                                                        ‫‪124‬‬\n\f      ‫الدعــوة واإلرشــاد بحائــل لطلــب رفــع فتــوى لســماحة مفتــي عــام اململكة‬\n      ‫العربيــة الســعودية بشــأن اإلفــادة مــن ســماحته عــن وقــوع طــاق الــزوج‬\n      ‫لزوجتــه املذكــورة؛ ووعــد والــد الزوجــة أنــه متــى مــا متــت اإلفــادة مــن‬\n      ‫ســماحة املفتــي يكــون رجــوع الزوجــة لزوجهــا حســب نــص الفتــوى؛‬\n      ‫فتوقفــت عــن إجــراءات العقــد لعــدم اكتمــال إجراءاتــه الشــرعية‬\n      ‫والنظاميــة؛ هــذا واهلل أســأل لنــا ولهــم الهدايــة والتوفيــق والســداد‬\n      ‫والرشــاد؛ املــأذون الشــرعي بحائــل؛ توقيعــه ) أه ـ ‪ .‬وبعــرض ذلــك علــى‬\n      ‫الطرفــن قــال املدعــي مــا ذكــره املــأذون غيــر صحيــح هكــذا قــال‬\n      ‫فقالــت املدعيــة مــا ذكــره املــأذون املــدون بعاليــه كلــه صحيــح هكــذا‬\n      ‫قالــت فقــال املدعــي مــرة ثانيــة أفيدكــم أن مــا ذكــره املــأذون بعضــه‬\n      ‫صحيــح وبعضــه غيــر صحيــح هكــذا قــال ثــم قــال إن هنــاك بعــض‬\n      ‫الوقائــع لــم يذكرهــا املــأذون وبعــض ماذكــره صحيــح وعنــدي شــهود‬\n      ‫علــى مراجعتــي لهــا وأحتمــل إن كانــت شــهادتهم غيــر صحيحــة هكــذا‬\n      ‫قــال؛ وإلحضــار شــهود املدعــي رفعــت اجللســة ليــوم اإلثنــن املوافــق‬\n      ‫‪1434/8/8‬ه ــالساعة التاســعة والنصــف صباحــا؛ وبــاهلل التوفيق وصلى‬\n      ‫اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن؛ حــرر يف يــوم‬\n         ‫األحــد املوافــق ‪1434/7/30‬ه ـ الســاعة العاشــرة والنصــف صباحــا‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعده وبعــد ففي هذا‬\n      ‫اليــوم االثنــن ‪1434/08/08‬ه ـ افتتحــت اجللســة بتمــام الســاعة العاشــرة‬\n      ‫والربــع صباح ـ ًا وفيهــا حضــر املدعــي واملدعــى عليهــا واملعــرف لهــا‬\n      ‫وبســؤال املدعــي عــن شــهوده قــال لقــد أحضرتهــم معــي يف هــذه اجللســة‬\n      ‫وأطلــب ســماع مــا لديهــم هكــذا قــال وحضــر للشــهادة وأدائهــا ســعودي‬\n      ‫وقــال كل واحــد منهمــا أشــهد هلل تعالــى أننــي مــن زمــاء املدعي بالعمل‬\n\n\n‫‪125‬‬\n\f‫وقــد رأيتــه ضايــق صــدره فســألته عــن ســبب ذلــك فقــال إننــي طلقــت‬\n‫زوجتــي طلقــه واحــدة وال أعــرف كيــف اســترجع زوجتــي وكان ذلــك‬\n‫بعــد طالقــه لهــا بشــهر ونصــف حســب قولــه فقلــت لــه ميكنــك إرجاعهــا‬\n‫مــا دامــت يف عدتهــا فقــال لــي إننــي أنتظــر فتــوى ســماحة مفتــي عــام‬\n‫اململكــة بهــذا املوضــوع وبعــد مــدة طلــب مني إثبات هذه الشــهادة فقمت‬\n‫ـدي مــن‬\n      ‫بإثبــات شــهادتي يف الورقــة املرفــق صورتهــا باملعاملــة هــذا مــا لـ ّ‬\n‫شــهادة هكــذا شــهد كل واحــد منهمــا مبفــرده ثــم قــال الشــاهد الثانــي‬\n‫وبعــد إفهامنــا للمدعــي أن لــه حــق اســترجاع مطلقتــه قــال املدعــي لقــد‬\n‫اســترجعت مطلقتــي قالــه حــال إفهامنــا لــه بذلــك هكــذا قــال وبســؤال‬\n‫الشــاهدين أنكمــا شــهدمتا علــى حســب قــول املدعــي أنــه طلقهــا قبــل‬\n‫شــهر ونصــف فهــل تعلمــا متــى تاريــخ طالقــه لهــا فقــال الشــاهد علــى‬\n‫حــد علمــي أنــه طلقهــا يف ‪1433/4/23‬ه هكــذا قــال وبســؤال املدعــي‬\n‫ـدي ســوى مــا تقدمــت بــه هكــذا‬     ‫هــل لديــك زيــادة بينــة فقــال ليــس لـ ّ‬\n‫قــال وبســؤال املدعيــة هــل لديــك مــا تريديــن إضافتــه فقالــت مــا جــاء‬\n‫بشــهادة الشــاهدين غيــر صحيــح وأنــا لــم يراجعنــي املدعــي ولــو كانــت‬\n‫دعــواه صحيحــة لوضــح ذلــك للدعــوة واإلرشــاد ولســماحة املفتــي حــال‬\n‫استفســاره وملــا أحضــر عاقــد األنكحــة لعقــد زواجي به مــرة أخرى هذا‬\n‫ـدي ســوى مــا أضفتــه هكــذا قالــت وإلقــرار‬    ‫مــا أريــد إضافتــه وليــس لـ ّ‬\n‫املدعــي بالطــاق ورجحــان بينــات املدعــى عليهــا التــي بحــد ذاتهــا تثبــت‬\n‫وقــوع الطــاق وخروجهــا منعدتهــا دون اســترجاع املدعــي لهــا وهــي يف‬\n‫عدتهــا فقــد ســألت املدعــى عليهــا هــل هــي مســتعدة باليمــن علــى عــدم‬\n‫اســترجاع املدعــي لهــا وهــي يف عدتهــا فقالــت مســتعدة بذلــك فأمرتهــا‬\n‫باحللــف فحلفــت بــاهلل تعالــى قائلــة واهلل العظيــم الــذي ال إلــه غيــره‬\n\n\n                                                                                      ‫‪126‬‬\n\f      ‫عالــم الغيــب والشــهادة أن املدعــي لــم يقــم باســترجاعي أثنــاء عدتــي‬\n      ‫بعــد طالقــه لــي هكــذا حلفــت وعليــه فقــد قــررت إغــاق بــاب املرافعــة‬\n      ‫ـاء علــى مــا ســبق مــن الدعــوى واإلجابــة‬‫وبعــد دراســة القضيــة وتأملهــا وبنـ ً‬\n      ‫واطالعــي علــى أوراق املعاملــة وإلقــرار املدعــي يف دعــواه بتطليــق املدعى‬\n      ‫عليهــا وملــا أفــادت بــه املدعــى عليهــا مــن أنهــا خرجــت مــن عدتهــا دون‬\n      ‫مراجعــة املدعــي لهــا وليمــن املدعــى عليهــا وتناقــض أقــوال املدعــي‬\n      ‫وتناقــض شــهادة شــاهديه وكونهــا جــاءت شــهادتهما املثبتــة يف الورقــة‬\n      ‫بعــد خروجهــا مــن عدتهــا يف ‪1433/10/11‬ه ـ وألن مــا جــاء بإفــادة‬\n      ‫كاتــب العــدل مــأذون األنكحــة تــدل داللــة واضحــة علــى طــاق املدعي‬\n      ‫للمدعــى عليهــا وأنهــا خرجــت مــن عدتهــا دون مراجعــة املدعــي لهــا حيث‬\n      ‫أحضــره املدعــي وطلــب منــه عقــد نكاحــه عليهــا للمــرة الثانيــة وملــا‬\n      ‫جــاء بفتــوى ســماحة مفتــي عــام اململكــة املرفــق صورتهــا باملعاملــة يف‬\n      ‫‪1433/10/18‬ه ـ ومضمونهــا أن املدعــي طلــق املدعــى عليهــا وهــي طلقة‬\n      ‫واحــدة ولــه العــود إليهــا بعقــد جديــد بشــروطه إذا لــم يراجعهــا هــذا‬\n      ‫مضمونــه واملدعــي لــم يثبــت رجوعــه حــال استفســاره وملــا نــص عليــه‬\n      ‫ابــن قدامــه يف املغنــي قــال ( املــرأة إذا ادعــت انقضــاء عدتهــا يف مــدة‬\n      ‫ميكــن انقضاؤهــا فيهــا قبــل قولهــا ) ‪ 563/10‬وجــاء يف كتــاب شــرح‬\n      ‫الزركشــي علــى مختصــر اخلرقــي مــا نصــه ( إذا قــال أرجتعتــك فقالــت‬\n      ‫انقضــت عدتــي قبــل رجعتــك فالقــول قولهــا مــع ميينهــا إذا ادعــت مــن‬\n      ‫ذلــك ممكنـ ًا ) ‪ 452/5‬وجــاء تفصيلــه يف صحيفــة ‪ 453‬لــكل مــا ســبق‬\n      ‫ـدي دعــوى املدعــي باســترجاعه للمدعــى عليهــا ‪.......‬‬        ‫فإنــه لــم تثبــت لـ ّ‬\n      ‫ـدي طــاق املدعــي‬   ‫أثنــاء عدتهــا الشــرعية بعــد طالقــه لهــا وقــد ثبــت لـ ّ‬\n      ‫للمدعــى عليهــا طلقــة واحــدة بعــد الدخــول واخللــوة وبــدون عــوض وأنهــا‬\n\n\n‫‪127‬‬\n\f‫خرجــت مــن عدتهــا دون مراجعــة املدعــي لهــا أثنــاء عدتهــا هــذا مــا ظهــر‬\n‫لــي وبــه حكمــت وأفهمــت املدعــي أنــه ليــس لــه الرجــوع للمدعــى عليهــا‬\n‫إال بعقــد ومهــر جديديــن وبرضاهــا وأن عليــه مراجعــة األحــوال املدنيــة‬\n‫إلســقاطها مــن كــرت العائلــة وبعــرض احلكــم علــى الطرفــن قــررت‬\n‫املدعــى عليهــا قناعتهــا بــه أمــا املدعــي فقــرر اعتراضــه بتقــدمي الئحــة‬\n‫اعتراضيــة وأفهــم أنــه ســيتم تســليمه لنســخة مــن احلكــم حــا ًال عبــر‬\n‫النظــام الشــامل ولــه مــدة ثالثــن يومـ ًا لتقــدمي مــا لديــه وإن انتهــت املــدة‬\n‫دون تقدمــه بالالئحــة ســقط حقــه واكتســب احلكــم القطعيــة وقــرر‬\n‫فهمــه لذلــك ‪ ،‬واهلل املوفــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n‫وصحبه وســلم ‪ .‬حرر يف ‪1434/8/8‬هـ الســاعة احلادية عشــر والنصف‬\n                                                                            ‫صباح ـ ًا ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي‬\n‫هــذا اليــوم األربعــاء ‪1434/11/05‬ه ـ افتتحــت اجللســة الســاعة العاشــرة‬\n‫ـاء علــى ورود املعاملــة مــن محكمــة االســتئناف‬        ‫والنصــف صباح ـ ًا ؛ بنـ ً‬\n‫بحائــل يف ‪1434/10/28‬ه ـ املرفــق بهــا قــرار أصحــاب الفضيلــة قضــاة‬\n‫محكمــة االســتئناف بدائــرة األحــوال الشــخصية يف ‪1434/10/26‬ه ـ‬\n‫ونــص حاجتــه ( وبدراســة الصــك ‪ ،‬وصــورة ضبطــه ‪ ،‬وأوراق املعاملــة ‪،‬‬\n‫والالئحــة االعتراضيــة ‪ ،‬قررنــا املصادقــة علــى مــا حكــم بــه فضيلتــه)‬\n‫أهــ‪ .‬وملصادقــة محكمــة االســتئناف للحكــم واكتســابه القطعيــة‪،‬‬\n‫ومت إحلــاق ذلــك بضبطــه وســجله حســب التعليمــات ‪ ،‬واهلل املوفــق‪،‬‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n             ‫‪1434/11/05‬ه ـ الســاعة العاشــرة وأربعــون دقيقــة صباح ـ ًا ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة دائــرة األحــوال‬\n\n\n                                                                                          ‫‪128‬‬\n\f      ‫الشــخصية مبحكمــة االســتئناف علــى املعاملــة الــواردة مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة املســاعد رفق كتابــه وتاريخ ‪1434/10/8‬هـ‪،‬‬\n      ‫واملقيــدة لدينــا وتاريــخ ‪1434/10/13‬ه ـ ‪ ،‬املرفــق بهــا الصــك الصــادر‬\n      ‫مــن فضيلــة الشــيخ‪ /‬القاضــي باحملكمــة العامــة بحائــل برقــم ‪........‬‬\n      ‫وتاريخ ‪1434/8/8‬هـ ‪ ،‬اخلاص بدعوى‪ ........ /‬ضد ‪ ........ /‬بشــان عودة‬\n      ‫الزوجــة ( انقيــاد ) ‪ ،‬وقــد تضمــن الصــك أنــه ثبــت لــدي فضيلتــه طــاق‬\n      ‫املدعــي للمدعــى عليهــا حســب مــا هــو موضــح يف الصــك‪ ،‬وبدراســة‬\n      ‫الصــك ‪ ،‬وصــورة ضبطــه ‪ ،‬وأوراق املعاملــة ‪ ،‬والالئحــة االعتراضيــة‬\n      ‫‪،‬قررنــا املصادقــة علــى مــا حكــم بــه فضيلتــه‪ ،‬مــع تنبيــه فضيلتــه إلــى‬\n      ‫نســخ إعــام احلكــم بخــط واضــح‪ ،‬واهلل املوفــق ‪ ،‬وصلــى اهلل علــى‬\n                                                ‫نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪129‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":121,"source_page_end":129,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9581cd7cdaab05e5917c6467a76fa730771ada22a055d92ab30c1c8cb39c0327","normalized_text_hash":"578c077b4b747849c0df72e0a1fb54a21f4acd900bf8804cd9c8235bb0538bf1","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p121-34291518"},{"id":"91749b71-e4f4-5ea7-ae35-9bc7f08d9ab7","document_type":"judgment","category":"judicial","subcategory":"general","title":"زوجية -طلب االنقياد لبيت الزوجية -موافقة الزوجة بعد تنفيذ شروط العقد -رفض تنفيذ بعض شروط العقد لعدم القدرة - إفهام الزوج أن عليه تطليق الزوجة لعدم وفائه بالشروط -طلب الزوجة فسخ النكاح -أحق الشروط أن يوفى ما استحللتم به الفروج -عدم توفيه شرط من شروط النكاح -احلكم بفسخ النكاح","document_number":"33333676","case_number":"33108641","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/7/8","year":"1434","subject":"زوجية -طلب االنقياد لبيت الزوجية -موافقة الزوجة بعد تنفيذ شروط العقد -رفض تنفيذ بعض شروط العقد لعدم القدرة - إفهام الزوج أن عليه تطليق الزوجة لعدم وفائه بالشروط -طلب الزوجة فسخ النكاح -أحق الشروط أن يوفى ما استحللتم به الفروج -عدم توفيه شرط من شروط النكاح -احلكم بفسخ النكاح","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33333676 :‬تاريخه ‪1433/7/8 :‬هـ‬\n                    ‫رقم الدعوى ‪33108641:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 3442422‬تاريخه‪1434/2/20:‬هـ‬\n\n\n‫زوجيــة ‪ -‬طلــب االنقيــاد لبيــت الزوجيــة ‪ -‬موافقــة الزوجــة بعــد تنفيــذ‬\n‫شــروط العقــد ‪ -‬رفــض تنفيــذ بعــض شــروط العقــد لعــدم القــدرة ‪-‬‬\n‫إفهــام الــزوج أن عليــه تطليــق الزوجــة لعــدم وفائــه بالشــروط ‪ -‬طلــب‬\n‫الزوجــة فســخ النــكاح ‪ -‬أحــق الشــروط أن يوفــى مــا اســتحللتم بــه‬\n‫الفــروج ‪ -‬عــدم توفيــه شــرط مــن شــروط النــكاح ‪ -‬احلكــم بفســخ النــكاح‬\n                                                                 ‫دون عــوض‪.‬‬\n\n\n\n                        ‫‪ .1‬قول اهلل تعالى (وال تضاروهن لتضيقوا عليهن)‬\n                   ‫‪ .2‬قول النبي صلى اهلل عليه وسلم (ال ضرر وال ضرار)‬\n        ‫‪ .3‬يف األثر (إن أحق الشروط أن يوفى ما استحللتم به الفروج)‬\n‫‪ .4‬قــال عبدالرحمــن بــن غنــم قــال ( كنــت مع عمــر بن اخلطاب ‪-‬رضي‬\n‫اهلل عنــه‪ -‬فجــاءه رجــل فقــال‪ :‬يــا اميــر املؤمنــن تزوجــت هذه واشــترطت‬\n‫لهــا دارهــا‪ ،‬وإنــي ألجمــع ألمــري أو لشــأني أن انتقــل إلــى أرض كــذا‬\n‫وكــذا فقــال‪( :‬لهــا شــرطها)‪ ،‬فقــال الرجــل‪ :‬هلــك الرجــال إذ ال تشــأ‬\n‫امــرأة أن تطلــق زوجهــا إال طلقــت‪ ،‬فقــال عمــر رضــي اهلل عنــه‪( :‬املؤمنون‬\n‫علــى شــروطهم عنــد مقاطــع حقوقهــم) قــال األلبانــي‪ :‬إســناده صحيــح‬\n      ‫علــى شــرط الشــيخني) [ينظــر‪ :‬إرواء الغليــل‪ ،‬وهــو برقــم‪.])1893( :‬‬\n‫‪ .5‬قــول ابــن قدامــة رحمــه اهلل ( الثانــي شــرط تنتفــع بــه املــرأة كزيــادة‬\n‫علــى مهرهــا ‪ ..‬أو أن ال يســافر بهــا وال ينقلهــا عــن دارهــا وبلدهــا‪ ،‬فهــذا‬\n\n                                                                                     ‫‪130‬‬\n\f      ‫صحيــح يلــزم الوفــاء بــه ‪ ..‬وألنــه شــرط لهــا فيــه نفــع ومقصــود ال ينــايف‬\n      ‫ـف بــه فلهــا فســخ‬‫مقصــود ال ِّنــكاح فصـ َّـح كال ِّزيــادة يف املهــر‪ ،‬فــإن لــم يـ ِ‬\n      ‫النــكاح؛ ألنــه شــرط الزم يف عقــد فثبــت حـ ّـق الفســخ بفواتــه كشــرط‬\n      ‫الرهــن يف البيــع)‪[ .‬ينظــر‪ :‬الــكايف ‪ ،39/3‬الشــرح الكبيــر ‪ ،526/7‬شــرح‬\n                                                                          ‫الزركشــي ‪)]139/5‬‬\n      ‫‪ .6‬قــول عمــر رضــي اهلل عنــه ( إذا أجيــف البــاب وأرخيــت الســتور فقــد‬\n                                                                    ‫وجــب املهــر ) البيهقــي‬\n      ‫‪ .7‬قاعــدة مــن وجــب عليــه شــيء وامتنــع عــن أدائــه أداة عنــه احلاكــم‬\n                                                                                       ‫الشــرعي‪.‬‬\n      ‫‪ .8‬أمــر النبــي صلــى اهلل عليــه وســلم (المــرأة ثابــت بــن قيــس أن تتربــص‬\n      ‫حيضــة واحــدة وتلحــق بأهلهــا وهــو مذهب جمع مــن الصحابة كأمير‬\n                  ‫املؤمنــن عثمــان وابــن عبــاس رضي اهلل عنهما) رواه النســائي‪.‬‬\n      ‫‪ .9‬قــول ابــن تيميــة رحمــه اهلل (املختلعــة يكفيهــا االعتــداد بحيضــة‬\n      ‫واحــدة‪ ،‬وهــي روايــة عــن أحمــد ومذهــب عثمــان بــن عفــان وغيــره‪،‬‬\n      ‫واملفســوخ نكاحهــا كذلــك أومــأ إليــه أحمــد يف روايــة صالــح)‬\n                                                                           ‫االختيــارات ‪.282‬‬\n      ‫‪ .10‬قــول ابــن القيــم (هــو مقتضــى قواعــد الشــريعة فــإن العــدة إمنــا‬\n      ‫جعلــت ثــاث حيــض ليطــول زمــن الرجعــة يف تــروي الــزوج ويتمكــن مــن‬\n      ‫الرجعــة يف مــدة العــدة‪ ،‬فــإذا لــم تكــن عليهــا رجعــة فاملقصــود مجــرد‬\n      ‫بــراءة رحمهــا مــن احلمــل وذلــك يكفــي فيــه حيضــة لالســتبراء) زاد‬\n                                                                               ‫املعــاد ‪.199/5‬‬\n\n\n\n\n‫‪131‬‬\n\f‫ادعــى زوج علــى زوجتــه يطالبهــا باالنقيــاد إلــى بيــت الزوجيــة‪ ،‬صادقــت‬\n‫املدعــى عليهــا بالنــكاح وقــررت أنــه ال مانــع لديهــا للرجــوع إلــى بيــت‬\n‫الزوجيــة إذا نفــذ املدعــي شــروط عقــد النــكاح وهــي‪-1 :‬إكمــال‬\n‫الدراســة ‪ -2‬تأمــن بيــت مســتقل ‪ -3‬شــراء ذهــب عبــارة عــن اثنتــي‬\n‫عشــر حبــة غوايــش وطقــم بحرينــي كامــل ‪ -4‬إقامــة وليمــة الــزواج يف‬\n‫قاعــة وافــق املدعــي عليــه علــى الشــرط األول والثانــي ورفــض الرابــع‬\n‫وأمــا الشــرط الثالــث فذكــر أنــه ال يســتطيع توفيــر الذهــب املوصــوف‬\n‫وأنــه ســوف يوفــر لهــا ذهب ـ ًا حســب اســتطاعته ‪ ،‬عرضــت احملكمــة‬\n‫الصلــح بــن الطرفــن فامتنعــت املدعــى عليهــا وطالبــت بفســخ نكاحهــا‬\n‫مــن املدعــي إذا لــم يوفــر لهــا الشــروط التــي ادعــت بهــا والن اخلــاف‬\n‫ـرط يف النــكاح‬ ‫احلاصــل بــن الزوجــن إمنــا هــو خــاف علــى تفويــت شـ ٍ‬\n‫وال يدخلــه اإللــزام ببعــث احلكمــن ومبــا أن املدعــي اقــر أن املدعــى‬\n‫عليهــا اشــترطت عليــه الذهــب املذكــور وقــرر عــدم اســتعداده بتنفيــذه‬\n‫وطلبــت املدعيــة فســخ نكاحهــا ألجــل ذلــك وألن املدعــي قــد أخــل‬\n‫بشــرط صحيــح الزم يوجــب فســخ النــكاح لقولــه صلــى اهلل عليــه وســلم‬\n‫(إن أحــق الشــروط أن يوفــى مــا اســتحللتم بــه الفــروج) قــررت احملكمــة‬\n‫فســخ نــكاح املدعــى عليهــا مــن املدعــى وأفهمــت املدعــى عليهــا‬\n‫بــأن عليهــا العــدة الشــرعية‪ ،‬اعتــرض املدعــي فالحظــت محكمــة‬\n‫االســتئناف أن العقــد املكتــوب بــن الطرفــن ليــس فيــه ســوى شــرطني‬\n‫إكمــال الدراســة وبيــت مســتقل وعلــى احملكمــة التأكــد مــن وجــود‬\n‫الشــرط الثالــث والرابــع بــن الطرفــن فســألت احملكمــة املدعــي عــن‬\n\n                                                                                  ‫‪132‬‬\n\f      ‫تاريــخ حصــول شــرط الذهــب والوليمــة فذكــر أن الشــرطني وقعــا قبــل‬\n                    ‫عقــد النــكاح‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده‪ ،‬وبعــد‪ :‬فلــدي أنــا (‪ ،)0000‬املــازم القضائــي لــدى‬\n      ‫فضيلــة الشــيخ‪ ، )0000( :‬القاضــي يف احملكمــة العامــة بالريــاض‪،‬‬\n      ‫والقائــم بعملــه فتــرة انتدابــه ملدينــة الطائــف مبوجــب الكتــاب رقــم‪ :‬يف‪:‬‬\n      ‫‪1433/7/2‬ه ـ وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلة مســاعد رئيس‬\n      ‫احملكمــة العامــة بالريــاض رقــم‪ :‬وتاريــخ‪1433/02/13 :‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم‪ :‬وتاريــخ ‪1433/2/13‬ه ففــي يــوم الثالثــاء املوافــق‪:‬‬\n      ‫‪1433/07/08‬ه ـ حضــر‪ )0000( ، :‬ســعودي اجلنســية مبوجــب الهويــة‬\n      ‫الوطنيــة رقــم‪ )00000( :‬وحضــرت حلضــوره‪ ،)0000( :‬ســعودية اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم‪ )00000( :‬واملعــرف بهــا مــن قبــل والدهــا‪:‬‬\n      ‫(‪،)0000‬ســعودي اجلنســية وادعــى األول قائــا‪ :‬إن هــذه احلاضــرة زوجــة‬\n      ‫لــي؛ فقــد عقــدت عليهــا بتاريــخ ‪1431/6/12‬ه ـ وأصدقتهــا‪ :‬خمســة‬\n      ‫وثالثــون ألــف ريــال‪ ،‬وقــد رفضــت أن أدخــل بهــا‪ ،‬وإلــى اآلن لــم أختلــي‬\n      ‫بهــا وأنــا راغــب بهــا‪ ،‬أطلــب إلزامهــا باالنقيــاد لبيــت الزوجيــة‪ ،‬هــذه‬\n      ‫دعــواي‪ .‬وبعــرض ذلــك علــى املدعــى عليهــا أجابــت قائلــة‪ :‬مــا ذكــره‬\n      ‫املدعــي مــن العقــد وتاريخــه والصــداق وقــدره فكلــه صحيــح‪ ،‬وأنــا قــد‬\n      ‫اســتلمت كامــل الصــداق‪ ،‬وأمــا مــا ذكــره مــن أننــي رافضــة بالدخــول‬\n      ‫عليــه فغيــر صحيــح‪ ،‬وأمامــا ذكــره أننــي لــم أختلــي بــه فغيــر صحيــح‬\n      ‫فقــد اختليــت بــه مــرار ًا يف الســيارة وذهبنــا ملطاعــم وجلــس معــي يف‬\n      ‫منــزل والــدي مــرات كثيــرة‪ ،‬وأنــا ليــس لــدي مانــع باالنقيــاد معــه لبيــت‬\n\n‫‪133‬‬\n\f‫الزوجيــة إذا نفــذ شــروطي‪ ،‬وهــي‪1 :‬ـ أن يوافــق علــى إكمــال دراســتي‪.‬‬\n‫‪2‬ـ أن يؤمــن لــي بيــت مســتقال‪3 .‬ـ أن يشــتري لــي ذهب ـ ًا وهــو عبــارة عــن‪:‬‬\n‫‪ 12‬حبــة غوايــش‪ ،‬وطقــم بحرينــي كامــل أســوة بغيــري مــن النســاء‪.‬‬\n‫‪4‬ـ أن يقيــم وليمــة زواج يف قاعــة‪ ،‬هكــذا أجابــت‪ .‬وبعــرض ذلــك علــى‬\n‫املدعــي أجــاب قائــا‪ :‬مــا ذكرتــه املدعــى عليهــا يف جوابهــا فكلــه‬\n‫صحيــح جملــة وتفصيــا عــدا الشــرط الرابــع‪ ،‬وأنــا غيــر مســتعد بتنفيــذ‬\n‫الشــرط الرابــع إطالقــا‪ ،‬وال مانــع لــدي أن أقيــم احلفــل يف اســتراحة‪ ،‬أما‬\n‫الشــرط الثالــث فــا أســتطيع توفيــر هــذا الذهــب املوصــوف إطالقــا‪،‬‬\n‫وســوف أوفــر لهــا ذهب ـ ًا حســب اســتطاعتي‪ ،‬هكــذا أجــاب‪ .‬وبســؤال‬\n‫املدعــى عليهــا عــن بينتهــا يف ذلــك أجابــت قائلــة‪ :‬ليــس لــدي بينــة علــى‬\n‫ذلــك‪ ،‬وأطلــب ميينــه علــى نفــي دعــواي ومســتعدة بعدهــا لالنقيــاد معــه‪،‬‬\n‫هكــذا أجابــت‪ .‬وبعــرض ذلــك علــى املدعــي أجــاب قائــا‪ :‬لــن أحلــف‬\n‫اليمــن إطالقـاً‪ ،‬هكــذا قــرر‪ .‬ثــم جــرى عــرض الصلــح ـ الــذي هــو خيـرـ‬\n‫علــى الطرفــن فامتنعــت املدعيــة وقــررت قائلــة‪ :‬إذا لــم يوفــر شــرطي‬\n‫الثالــث املذكــور أعــاه فأنــا غيــر راغبــة فيــه‪ ،‬وأطلــب فســخ نكاحــي‬\n‫منــه‪ ،‬هكــذا قــررت‪ .‬ونظــرا لوصــول القضيــة لهــذا احلـ ّـد أفهمــت‬\n‫املدعــي بتطليــق زوجتــه املدعيــة فقــرر قائــا‪ :‬لــن أطلقهــا إطالقـاً‪ ،‬وأنــا‬\n‫غيــر قــادر أن أوفــر لهــا الذهــب املوصــوف أعــاه وال أن أقيــم احلفــل‬\n‫يف قاعــة‪ ،‬وأطلــب انقيادهــا لبيــت الزوجيــة‪ ،‬هكــذا قــرر‪ .‬فبنــاء علــى‬\n‫مــا ســلف‪ ،‬وألن اخلــاف احلاصــل بــن الزوجــن إمنــا هــو خــاف علــى‬\n‫ـرط يف ال ِّنــكاح وال يدخلــه اإللــزام ببعــث احلكمــن‪ ،‬ومبــا أن‬  ‫توفيــة شـ ٍ‬\n‫املدعــي قــد أقـ ّـر أن املدعــى عليهــا قــد اشــترطت عليــه‪ :‬أن يشــتري لهــا‬\n‫ذهبـ ًا وهــو عبــارة عــن‪ 12 :‬حبــة غوايــش‪ ،‬وطقــم بحرينــي كامــل‪ ،‬وقــرر‬\n\n\n                                                                                    ‫‪134‬‬\n\f      ‫عــدم اســتعداده بتنفيــذ شــرطها املذكــور آنف ـ ًا لعــدم قدرتــه‪ ،‬وقــررت‬\n       ‫املدعيــة طلبهــا فســخ نكاحهــا ألجــل ذلــك‪ ،‬وألن املدعــى عليــه قــد أخــلَّ‬\n      ‫بشــرط صحيــح الزم يوجـ ُـب ـ اإلخــال بــه ـ فســخ ال ِّنــكاح‪ ،‬ملــا روى‬\n      ‫ـاري ومســلم واللفــظ لــه مــن حديــث عقبــة بــن عامــر ـ رضــي اهلل‬         ‫البخـ ّ‬\n      ‫عنــه ـ قــال‪ :‬قــال رســول اهلل صلــى اهلل عليــه وســلم ـ (إن أحــق الشــروط‬\n      ‫أن يوفــى مــا اســتحللتم بــه الفــروج)‪ ،‬وملــا روى البيهقــي وســعيد بــن‬\n      ‫منصــور واللفــظ لــه‪ ،‬عــن عبدالرحمــن بــن غنــم قــال ‪ :‬كنــت مــع عمــر‬\n      ‫بــن اخلطــاب ـ رضــي اهلل عنــه ـ فجــاءه رجــل فقــال‪ :‬يــا أميــر املؤمنــن‬\n      ‫ـترطت لهــا دارهــا‪ ،‬وإنــي ألجمــع ألمــري ـ أو لشــأني ـ‬ ‫ْ‬      ‫تزوجــت هــذه واشـ‬\n      ‫أن انتقــل إلــى أرض كــذا وكــذا فقــال‪( :‬لهــا شــرطها)‪ ،‬فقــال الرجــل‪:‬‬\n      ‫هلــك الرجــال إذ ال تشــأ امــرأة أن تطلــق زوجهــا إال طلقــت‪ ،‬فقــال عمــر‬\n      ‫ـ رضــي اهلل عنــه ـ ‪( :‬املؤمنــون علــى شــروطهم عنــد مقاطــع حقوقهــم)‪،‬‬\n      ‫قــال األلبانــي‪ :‬إســناده صحيــح علــى شــرط الشــيخني‪[ .‬ينظــر‪ :‬إرواء‬\n                                                        ‫الغليــل‪ ،‬وهــو برقــم‪،])1893( :‬‬\n      ‫وملــا قــرره الفقهــاء يف ذلــك؛ يقــول ابــن قدامــة ـ رحمــه اهلل ـ (الثانــي‪:‬‬\n      ‫شــرط تنتفــع بــه املــرأة كزيــادة علــى مهرهــا ‪ . . .‬أو أن ال يســافر بهــا وال‬\n      ‫ينقلهــا عــن دارهــا وبلدهــا‪ ،‬فهــذا صحيــح يلــزم الوفــاء به ‪ . . .‬وألنه شــرط‬\n      ‫كالزيــادة يف‬‫ِّ‬      ‫لهــا فيــه نفــع ومقصــود ال ينــايف مقصــود ال ِّنــكاح فصـ َّـح‬\n      ‫ـف بــه فلهــا فســخ النــكاح؛ ألنــه شــرط الزم يف عقــد‬        ‫املهــر‪ ،‬فــإن لــم يـ ِ‬\n      ‫فثبــت حـ ّـق الفســخ بفواتــه كشــرط الرهــن يف البيــع)‪[ .‬ينظــر‪ :‬الــكايف‬\n      ‫‪ ،39/3‬الشــرح الكبيــر ‪ ،526/7‬شــرح الزركشــي ‪،]139/5‬وألن‬\n      ‫اإلخــال بالشــرط املذكــور ليــس بســبب مــن جهــة املدعيــة حتــى يتعـ ّـن‬\n      ‫إعادتهــا للمهــر‪ ،‬بــل هــو مبنـ ّـي علــى إخــال املدعــى عليــه بالقيــام بشــرط‬\n\n\n‫‪135‬‬\n\f‫الزم مــن الشــروط التــي اشــترطت عليــه يف ال ِّنــكاح‪ ،‬وهــذه جنايــة منــه‬\n‫علــى نفســه‪ ،‬وألن مــن ُشــرط عليــه شــرط صحيــح حــال العقــد واختلــى‬\n‫ا بالفســخ؛ ملــا روى البيهقــي عــن‬  ‫ـف بــه وجــب املهــر كامـ ً‬ ‫بزوجتــه ولــم يـ ِ‬\n‫عم ـرـ رضــي اهلل عنــه ـ أنــه قــال‪( :‬إذا أجيــف البــاب وأرخيــت الســتور‬\n‫ـرر‬\n‫فقــد وجــب املهــر)‪ ،‬وال نتــرك املدعيــة مع َّلقــة ـ واحلــال هــذه ـ ضـ ٌ‬\n‫بالــغ‪ ،‬والضــرر يــزال‪ ،‬وقــد ُشــرع رفــع الضــرر بالفرقــة بــن الزوجــن‪،‬‬\n‫ولقــول اهلل ـ تعالــى ـ ‪(:‬وال تضاروهــن لتضيقــوا عليهــن)‪ ،‬ولقــول النبــي‬\n‫ـ صلــى اهلل عليــه وســلم ـ ‪( :‬ال ضــرر وال ضــرار)‪ ،‬وألن مــن وجــب عليــه‬\n‫ـرعي؛ لذلــك كلــه فقــد‬‫شــيء وامتنــع عــن أدائــه أ ّداه عنــه احلاكــم الشـ ّ‬\n‫فســخت نــكاح املدعــى عليهــا‪ :‬ســجل املدنــي رقــم‪ :‬مــن زوجهــا املدعــي‪:‬‬\n‫بــدون عــوض‪ ،‬وبذلــك قضيــت‪ .‬وبإعــان احلكــم عليهمــا قــررت املدعيــة‬\n‫قناعتهــا باحلكــم‪ ،‬أمــا املدعــى عليــه فقــرر اعتراضــه علــى احلكــم‬\n‫اعتراضيــة‪ ،‬فأعطــي نســخة مــن احلكــم‪ ،‬وأفهــم‬  ‫ّ‬         ‫ـتعد بتقــدمي الئحــة‬\n                                                                              ‫واسـ َّ‬\n‫بــأن لــه احلــق يف تقــدمي اعتراضــه ملــدة ثالثــن يومـ ًا اعتبــار ًا مــن تاريخ هذا‬\n‫حقــه يف‬\n       ‫اليــوم‪ ،‬وأنــه إذا لــم يقــدم اعتراضــه خــال هــذه الفتــرة ســقط ّ‬\n‫القطعيــة‪ .‬وأفهمــت املدعيــة بأنــه ال يحــل‬\n                                        ‫ّ‬           ‫االعتــراض واكتســب احلكــم‬\n‫لهــا أن تتــزوج إال بعــد اكتســاب احلكــم القطعيــة‪ ،‬وتبــن مــن ســؤالي‬\n‫ـرعية لهــذا الفســخ وهــي‪:‬‬\n                         ‫لهــا أن ذات أقــراء فأفهمتهــا بــأن عليهــا عـ ّـدة شـ ّ‬\n‫حيضــة واحــدة يف أصــح قولــي العلمــاء؛ ملــا روى النســائي أن النبــي ـ صلــى‬\n‫اهلل عليــه وســلم ـ أمــر امــرأة ثابــت بــن قيــس أن تتربــص حيضــة واحــدة‬\n‫وتلحــق بأهلهــا‪ ،‬وهــو مذهــب جمــع مــن الصحابــة كأميــر املؤمنــن‬\n‫عثمــان وابــن عبــاس رضــي اهلل عنهــم‪ ،‬قــال ابن تيميــة ـ رحمه اهلل تعالى‪:‬‬\n‫(املختلعــة يكفيهــا االعتــداد بحيضــة واحــدة‪ ،‬وهــي روايــة عــن أحمــد‬\n\n\n                                                                                           ‫‪136‬‬\n\f      ‫ومذهــب عثمــان بــن عفــان وغيــره‪ ،‬واملفســوخ نكاحهــا كذلــك أومــأ‬\n      ‫إليــه أحمــد يف روايــة صالــح )‪ .‬ا‪.‬ه ـ [ينظــر‪ :‬االختيــارات ‪ ،]282‬وقــال ابــن‬\n      ‫القيــم ـ رحمــه اهلل تعالىــ‪( :‬وهــي مقتضــى قواعــد الشــريعة فــإن العــدة إمنــا‬\n      ‫جعلــت ثــاث حيــض ليطــول زمــن الرجعــة يف تــروى الــزوج ويتمكــن مــن‬\n      ‫الرجعــة يف مــدة العــدة‪ ،‬فــإذا لــم تكــن عليهــا رجعــة فاملقصــود مجــرد‬\n      ‫بــراءة رحمهــا مــن احلمــل وذلــك يكفــي فيــه حيضــة لالســتبراء)‪ .‬ا‪.‬ه ـ‬\n      ‫[ينظــر‪ :‬زاد املعــاد ‪ ،]5/199‬كمــا أفهمتهمــا بأنهمــا بانــا بينونــة صغــرى‬\n      ‫ال يحــل أحدهمــا لآلخــر إال بعقــد جديــد مكتمــل الشــروط واألركان‪.‬‬\n      ‫هــذا وســوف يتــم التهميــش علــى عقــد النــكاح ـ مبــا طــرأ عليــه ـ بعــد‬\n      ‫القطعيــة‪ .‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا‬\n                                                         ‫ّ‬         ‫اكتســاب احلكــم‬\n                         ‫محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‪1433/7/8 :‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا يف احملكمــة العامــة بالريــاض ويف يــوم‬\n      ‫الســبت املوافــق‪1434/01/10‬ه افتتحــت اجللســة الســاعة احلاديــة عشــر‬\n      ‫والنصــف وفيهــا حضــر الطرفــان وقــد وردنــا قــرار محكمــة االســتئناف‬\n      ‫رقــم ‪ 33454251‬يف ‪1433/11/14‬ه ـ املرفــق بخطــاب فضيلــة‬\n      ‫مســاعد رئيــس محكمــة االســتئناف يف ‪1433/11/24‬ه ـ واملتضمــن‬\n      ‫(تكليفــي بإكمــال مــا يلــزم نحــو مالحظــات االســتئناف دون التعــرض‬\n      ‫للحكــم وبالطــاع علــى قــرار محكمــة االســتئناف الســابق وجدتــه‬\n      ‫يف ‪1433/9/4‬ه ـ واملتضمــن (املالحظــة بــأن فضيلــة حاكــم القضيــة‬\n      ‫لــم يتحقــق مــن أن الشــرط الــذي بنــى عليــه الفســخ إلخــال املدعــي بــه‬\n      ‫مبضمــون شــروط عقــد النــكاح أو أنــه شــرط حصــل بعــد العقــد والعقد‬\n      ‫املرفــق لــم يتضمــن ســوى شــرطني همــا إكمــال دراســتها حســب رغبتهــا‬\n      ‫وبيــت مســتقل فعلــى فضيلتــه التحقــق مــن ذلــك ومناقشــته بحضــور‬\n\n\n‫‪137‬‬\n\f‫الطرفــن وإجــراء مــا يلــزم) وعليــه فقــد ســألت املدعي عــن تاريخ حصول‬\n‫هــذا الشــرط فقــال إن التاريــخ كان يف ‪1431/6/2‬ه ـ وبعــرض ذلــك‬\n‫علــى املدعــى عليهــا صادقــت عليــه وبالنظــر إلــى عقــد النــكاح وجدتــه‬\n‫مبرمــا يف ‪1431/6/12‬ه ـ برقــم ‪ 173‬ومصــدره املــأذون الشــرعي هــذا‬\n‫مــا لزمــت اإلفــادة بــه مــن قبلــي كمســتخلف دون التعــرض للحكــم‬\n‫وعليهــا ختمــت اجللســة الســاعة ‪ 11.45‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/1/10‬ه ـ‬\n‫احلمد هلل وحده وبعد ففي يوم السبت املوافق‪1434/03/21‬هـ افتتحت‬\n‫اجللســة الســاعة ‪11.15‬وقــد وردتنــا املعاملــة مــن محكمــة االســتئناف‬\n‫باخلطــاب رقــم وتاريــخ ‪1434/3/2‬ه ـ مشــفوعا بــه قــرار التصديــق رقــم‬\n‫يف ‪1434/2/20‬ه واملتضمــن (وحيــث ســبق دراســة الصــك وصــورة‬\n‫ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة وباالطــاع علــى مــا أجاب‬\n‫بــه فضيلــة القاضــي وأحلقــه بالصــك بنــاء علــى قرارنــا رقــم ‪33100972‬‬\n‫وتاريــخ ‪1433/9/4‬ه ـ تقــرر الدائــرة املصادقــة علــى احلكــم بعــد اجلــواب‬\n‫األخيــر) قاضــي اســتئناف توقيعــه قاضــي اســتئناف توقيعــه رئيــس‬\n‫الدائــرة توقيعــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                               ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/3/21‬ه‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة املختصــة‬\n‫بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n‫علــى املعاملــة الــواردة بخطــاب فضيلــة رئيــس احملكمــة العامــة بالرياض‬\n‫املســاعد وتاريــخ ‪1434/2/2‬ه املرفــق بهــا الصــك الصــادر مــن فضيلــة‬\n‫املــازم القضائــي باحملكمــة الشــيخ‪ )0000(/‬وتاريــخ ‪1433/7/8‬ه‬\n‫اخلــاص بدعــوى(‪ )0000‬ضــد (‪ )0000‬بشــأن انقيــاد الزوجــة وقــد تضمــن‬\n\n\n                                                                                      ‫‪138‬‬\n\f      ‫الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وحيــث ســبق‬\n      ‫دراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة‬\n      ‫وباإلطــاع علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالصــك بنــاء علــى‬\n      ‫قرارنــا وتاريــخ ‪1433/9/4‬ه ـ تقــرر الدائــرة املصادقــة علــى احلكــم بعــد‬\n      ‫اجلــواب األخيــر‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n      ‫وصحبــه وســلم‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد و علــى آلــه‬\n                                                                     ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪139‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":130,"source_page_end":139,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"aecb9089030c187e10fc20aaac162be318026192921edd64e82191019b5ac782","normalized_text_hash":"a6a0e82a24004a1960413d4538f26cb3154f37356d768b06d9c127acd3815c18","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p130-33333676"},{"id":"fb0d44ab-57eb-5307-87e0-c3dd47f1cfed","document_type":"judgment","category":"judicial","subcategory":"general","title":"زوجية -إلزام الزوجة باالنقياد للطاعة -طلب الزوجة فسخ النكاح دون عوض -جرى محاولة الصلح بن الطرفن عدة مرات با جدوى -عينت المحكمة حكمن رأيا التفريق -احلكم بفسخ النكاح با عوض .","document_number":"3426340","case_number":"33173127","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/28","year":"1434","subject":"زوجية -إلزام الزوجة باالنقياد للطاعة -طلب الزوجة فسخ النكاح دون عوض -جرى محاولة الصلح بن الطرفن عدة مرات با جدوى -عينت المحكمة حكمن رأيا التفريق -احلكم بفسخ النكاح با عوض .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 3426340 :‬تاريخه ‪1434/1/28 :‬هـ‬\n                  ‫رقم الدعوى ‪33173127:‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34219575‬تاريخه‪1434/5/22 :‬هـ‬\n\n\n‫زوجيــة ‪ -‬إلــزام الزوجــة باالنقيــاد للطاعــة ‪ -‬طلــب الزوجــة فســخ‬\n‫النــكاح دون عــوض ‪ -‬جــرى محاولــة الصلــح بــن الطرفــن عــدة مــرات‬\n‫بــا جــدوى ‪ -‬عينــت احملكمــة حكمــن رأيــا التفريــق ‪ -‬احلكــم بفســخ‬\n                                                   ‫النــكاح بــا عــوض ‪.‬‬\n\n\n\n\n‫‪ .1‬قــول اهلل تعالــى (وإن خفتــم شــقاق بينهمــا فابعثــوا حكمــا مــن أهلــه‬\n                  ‫وحكمــا مــن أهلهــا إن يريــدا إصالحــا يوفــق اهلل بينهمــا)‬\n                 ‫‪ .2‬قول الرسول صلى اهلل عليه وسلم (ال ضرر وال ضرار)‬\n‫‪ .3‬مــا رواه البخــاري عــن ابــن عبــاس رضــي اهلل عنهمــا قــال جــاءت امــرأة‬\n‫ثابــت بــن قيــس بــن شــماس إلــى النبــي صلــى اهلل عليــه وســلم فقالــت‬\n‫يــا رســول اهلل مــا أنقــم علــى ثابــت يف ديــن وال خلــق إال أنــي أخــاف‬\n‫الكفــر يف اإلســام فقــال رســول اهلل صلــى اهلل عليــه وســلم (أترديــن‬\n                 ‫عليــه حديقتــه قالــت نعــم فــردت عليــه فأمــره ففارقهــا)‬\n                                 ‫‪ .4‬املادة ‪ 178‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n‫ادعــى زوج بدعــوى يطالــب زوجتــه بالتــزام طاعتــه باملعــروف‪ ،‬رفضــت‬\n‫املدعــى عليهــا الرجــوع إلــى بيــت املدعــي ملرضــه النفســي ملا يترتــب عليها‬\n\n                                                                                    ‫‪140‬‬\n\f      ‫مــن أضــرار وذكــرت أن املدعــي تهجــم عليهــا وضربهــا هــي وأوالدهــا‬\n      ‫ضربــا مبرح ـ ًا وهددهــم بالقتــل وطلبــت احلكــم بفســخ نكاحهــا‬\n      ‫منــه وتقدمــت بدعــوى رســمية جــرى إحالتهــا للقاضــي نفســه‪ ،‬قــررت‬\n      ‫احملكمــة الكتابــة إلــى قســم الصلــح فــورد قــرار مكتــب الصلــح‬\n      ‫باحملكمــة مت الصلــح واالتفــاق علــى أن يتــم فســخ النــكاح مقابــل مــا‬\n      ‫للزوجــة مــن نفقــة‪ ،‬وبعــرض القــرار أجــاب املدعــي أنــه غيــر موافــق‬\n      ‫علــى الصلــح وأنــه أجبــر علــى التوقيــع وأنــه ليــس مســتعدا باملخالعــة‬\n      ‫ثــم وافــق علــى املخالعــة إذا ردت املدعيــة الذهــب الــذي أخذتــه منــه‪،‬‬\n      ‫وعظــت احملكمــة الزوجــة للرجــوع إلــى بيــت زوجهــا فأصــرت علــى‬\n      ‫عــدم الرجــوع وطلبــت الفســخ‪ ،‬قــررت احملكمــة التريــث يف احلكــم‬\n      ‫أمــا يف أن يصطلحــا ألنهمــا كبيــران يف الســن وبينهمــا عشــرة طويلــة‬\n      ‫وأوالد‪ ،‬يف جلســة أخــرى أعــادت احملكمــة نصــح الزوجــن ثــم قــررت‬\n      ‫الكتابــة للحكمــن وقــرر الطرفــان أن قــرار احلكمــن ملــزم لهمــا ثــم‬\n      ‫ورد قــرار احلكمــن بأنهمــا رأيــا أن يفرقــا بــن الزوجــن بــدون عــوض‬\n      ‫وبعــرض القــرار علــى الطرفــن قنعــت بــه املدعــى عليهــا وقــررت أنهــا مــن‬\n      ‫ذوات اإلقــراء وقــرر املدعــي عــدم قناعتــه بــه‪ ،‬وملــا قــرره احلكمــان مــن‬\n      ‫التفريــق بــن املدعــي واملدعــى عليهــا بــدون عــوض ونظــر ًا ألن اســتمرار‬\n      ‫احليــاة الزوجيــة بــن الطرفــن علــى هــذا الوضــع ال يتحقــق منــه مقاصــد‬\n      ‫النكاح يف الشريعة ولقوله صلى اهلل عليه وسلم (ال ضرر وال ضرار)‪،‬‬\n      ‫لــذا حكمــت احملكمــة بفســخ نــكاح املدعــى عليهــا مــن املدعــي بــا‬\n      ‫عــوض وأفهمتهــا بــأن عليهــا العــدة الشــرعية‪ ،‬اعتــرض املدعــي‪ ،‬صــدق‬\n                                                      ‫احلكــم محكمــة االســتئناف‪.‬‬\n\n\n\n‫‪141‬‬\n\f‫احلمــد هلل وحــده‪ ،‬وصلــى اهلل وســلم علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪..‬‬\n‫فلــدي أنــا (‪ ، )0000‬القاضــي يف احملكمــة العامــة باملدينة املنورة ‪ ،‬بناء‬\n‫علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة املســاعد‬\n‫وتاريــخ ‪1433/3/9‬ه ـ املقيــدة باحملكمــة وتاريــخ ‪1433/03/09‬ه ـ‬\n‫واملتعلقــة بدعــوى يف طلبهــا معاشــرته باملعــروف‪ ،‬يف يــوم الثالثــاء املوافق‬\n‫‪1433/05/25‬ه ـ افتتحــت اجللســة الســاعة العاشــرة صباح ـ ًا ‪ ،‬وفيهــا‬\n‫حضــر (‪ )0000‬ســوري اجلنســية وحضــرة حلضــوره باملجلــس الشــرعي‪،‬‬\n‫ا ‪ :‬إن هــذه‬ ‫(‪ )0000‬ســورية اجلنســية‪ ،‬وبســؤاله عــن دعــواه ادعــى قائ ـ ً‬\n‫احلاضــرة زوجتــي منــذ تســعة عشــرة ســنة ‪ ،‬ولــي منهــا أربعــة أوالد هــم‬\n‫(‪ )0000‬وعمــره تســعة عشــرة عامــا ‪ ،‬و(‪ )0000‬وعمــره خمســة عشــر‬\n‫ســنة ‪ ،‬و(‪ )0000‬وعمــره ثمانــي ســنوات ‪ )0000( ،‬وعمــره ســت ســنوات‬\n‫‪ ،‬وال تقــوم مبــا يجــب لــي عليهــا شــرع ًا مــن االنقيــاد للطاعــة‪ ،‬واملعاشــرة‬\n‫باملعــروف ‪ .‬أطلــب احلكــم عليهــا بإلزامهــا بطاعتــي باملعــروف ‪ .‬هــذه‬\n‫دعــواي ‪ .‬وبعــرض ذلــك علــى املدعــى عليهــا أجابــت قائلــة‪ :‬مــا ذكــره‬\n‫املدعــي مــن زواجنــا واألوالد وأعمارهــم فصحيــح ‪ ،‬ولكنــي لســت‬\n‫مســتعدة بالرجــوع إليــه ألنــه مريــض نفســي ومرضــه مزمــن ورجوعــي‬\n‫إليــه يترتــب عليــه أضــرار كثيــرة ‪ ،‬منهــا تهجمــه علــي ‪ ،‬وضربــه املبــرح‬\n‫لــي وألوالدنــا ‪ ،‬بــل وخنــق األوالد ‪ ،‬وتهديدنــا بالقتــل ‪ ،‬واتهامــه لــي‬\n‫بأنــي أريــد قتلــه بالســم وغيــره ‪ ،‬ومحاولتــه التحــرش بأوالدنــا الصغــار‬\n‫والكبــار ‪ ،‬وأطلــب احلكــم عليــه بفســخ نكاحــي منــه ‪ ،‬وقــد تقدمــت‬\n‫بدعــوى يف هــذه احملكمــة أحيلــت إليكــم يف ‪1433/03/29‬ه ـ أطلــب‬\n\n                                                                                       ‫‪142‬‬\n\f      ‫فيهــا فســخ نكاحــي مــن املدعــي لألســباب التــي ذكرتهــا ‪ .‬هكــذا‬\n      ‫أجابــت ‪ .‬لــذا قــررت إحالتهــم لقســم الصلــح للتوفيــق بينهــم وإفادتنــا‬\n      ‫بذلــك‪ .‬ويف يــوم األحــد املوافــق ‪1433/07/13‬ه ـ افتتحــت اجللســة ‪،‬‬\n      ‫وفيهــا حضــر الطرفــان وقــد عــادت املعاملــة مــن قســم الصلــح مرفق ـ ًا‬\n      ‫ـاء‬\n        ‫بهــا قــرار الصلــح رقــم ‪ 88‬يف ‪1433/6/16‬ه ـ املتضمــن مــا نصــه‪( :‬بنـ ً‬\n      ‫علــى االســتدعاء املقــدم مــن (‪ )0000‬ضــد زوجهــا (‪ )0000‬بشــأن طلــب‬\n      ‫فســخ نكاحهــا‪ ،‬وطلــب الــزوج انقيــاد الزوجــة لبيــت الطاعــة‪ ،‬وبعــد‬\n      ‫اجللــوس مــع الطرفــن ومحاولــة اإلصــاح بينهمــا ومناقشــة أســباب‬\n      ‫اخلــاف والشــقاق مت الصلــح واالتفــاق علــى اآلتــي ‪ ، -1‬يتــم فســخ نكاح‬\n      ‫(‪ )0000‬مــن زوجهــا (‪ )0000‬باخللــع مقابــل مــا للزوجــة مــن نفقــة خــال‬\n      ‫الفتــرة املاضيــة‪ -2 .‬أن يذكــر كل واحــد منهمــا اآلخــر بخيــر لقولــه‬\n      ‫تعالــى ( وال تنســوا الفضــل بينكــم ) وعلــى هــذا مت الصلــح واالتفــاق‬\n      ‫وأذنــا ملــن يشــهد واهلل خيــر الشــاهدين)ا‪.‬هـ الزوجــة (‪ )0000‬توقيعهــا‬\n      ‫الــزوج (‪ )0000‬توقيعــه‪ ،‬املستشــار الشــرعي توقيعــه ‪ ،‬رئيــس قســم‬\n      ‫الصلــح (‪ )0000‬توقيعــه‪ .‬وبعــرض مــا ورد يف قــرار قســم الصلــح أجــاب‬\n      ‫املدعــي قائــا‪ :‬إننــي غيــر موافــق علــى هــذا الصلــح وقــد أجبــرت علــى‬\n      ‫التوقيــع‪ ،‬ولســت مســتعد ًا باملخالعــة بهــذه الطريقــة‪ ،‬وســأخالع حينمــا‬\n      ‫تــرد لــي الذهــب الــذي أخذتــه منــي والــذي ادعيــت بــه لديكــم‪ .‬هكــذا‬\n      ‫أجــاب‪ .‬وللتأمــل رفعــت اجللســة ‪ .‬ويف يــوم األحد املوافــق ‪1433/09/03‬هـ‬\n      ‫افتتحــت اجللســة الســاعة احلاديــة عشــرة ‪ ،‬وفيهــا حضــر الطرفــان‪،‬‬\n      ‫وحضــر (‪ )0000‬معــرف الــزوج ابنهــا ‪ )0000(،‬ســوري اجلنســية ‪ ،‬ثــم‬\n      ‫جــرى وعــظ الزوجــة بالرجــوع لبيــت زوجهــا ‪ ،‬وأن هــذا أصلــح للحــال‬\n      ‫واملــال ولهــا يف هــذا األجــر العظيــم ‪ ،‬كمــا جــرى وعظهــا وتذكيرهــا‬\n\n\n‫‪143‬‬\n\f‫بوجــوب طاعــة الــزوج ‪ ،‬وأن طاعتــه والصبــر عليــه مــن أفضــل األعمــال‬\n‫الصاحلــة ‪ ،‬فأصــرت علــى موقفهــا بعــدم الرجــوع وطلــب الفســخ‪ ،‬وألن‬\n‫لدينــا دعــوى بــن الطرفــن يف (ذهــب) مقيــدة ولــم يتــم حســمها حتــى‬\n‫اآلن ‪ ،‬وقــد ظهــر لــي أنهــا هــي ســبب النفــرة بــن الزوجــن خاصــة وأن‬\n‫الزوجــن كبيريــن وبينهمــا عشــرة طويلــة وأوالد ؛ لــذا قــررت التريــث‬\n      ‫ا يف أن يصطلحــا علــى أمــر مــرض لهمــا وألبنائهمــا‪.‬‬    ‫باحلكــم أم ـ ً‬\n‫ويف يــوم الســبت املوافــق ‪1434/01/03‬ه ـ افتتحــت اجللس ـ ًة ‪ ،‬وفيهــا‬\n‫حضــر الزوجــان برفقــة املعــرف (‪ )0000‬ابنهمــا‪ ،‬مبوجــب اإلقامــة‬\n‫رقــم (‪ ، )0000‬وفيهــا جــرى وعــظ الزوجــة بــأن ترجــع لزوجهــا وأن‬\n‫حتتســب األجــر وأن صبرهــا علــى زوجهــا أعظــم القربــات وأن رجوعهــا‬\n‫لزوجهــا فيــه لــم لشــمل األســرة ‪ ،‬وأن لــم شــمل األســرة ســبب لنجــاح‬\n‫األوالد يف حياتهــم واســتقرارهم ‪ ،‬وأن ذلــك ســبب لبرهــم إن شــاء اهلل‬\n‫تعالــى ‪ ،‬كمــا جــرى وعــظ الــزوج مبحاولــة البحــث عــن مــن يؤثــر عليهــا‬\n‫مــن النســاء أو مــن أهلهــا وأن عليــه إبــداء مــا يرهــا‪ ،‬ثــم جــرى عــرض‬\n‫احلكمــن علــى الزوجــن فأختــار الــزوج (‪ ، )0000‬واختــارت الزوجــة‬\n‫رئيــس قســم الصلــح يف هــذه احملكمــة الشــيخ(‪ ،)0000‬وقــررا قائلــن ‪:‬‬\n‫إن قــرار احلكمــن املذكوريــن ملــزم لهمــا ‪ .‬هكــذا قــررا ‪ .‬ولــورود قرار‬\n‫احلكمــن رفعــت اجللســة ‪ .‬ويف يــوم األربعــاء املوافــق ‪1434/01/28‬ه ـ‬\n‫افتتحــت اجللســة ‪ ،‬وفيهــا حضــر املتداعيــان مــع املعــرف‪ ،‬وقــد عــادت‬\n‫املعاملــة مــن قســم الصلــح باخلطــاب رقــم يف ‪1434/01/25‬ه ـ مرفــق‬\n‫بــه القــرار رقــم ‪ 19‬يف ‪1434/01/24‬ه ـ ونــص احلاجــة منــه « ســمعنا‬\n‫أصــل املشــكلة حيــث طلــب أن زوجتــه ترجــع لبيتــه وتعــود احليــاة بينهمــا‬\n‫وبعــرض ذلــك علــى الزوجــة قالــت زوجــي يضربنــي ويســيء عشــرتي وال‬\n\n\n                                                                                   ‫‪144‬‬\n\f      ‫ينفــق علــي وضعيــف جنســي ًا وقــد أنكــر الــزوج أنــه ضعيــف جنســي ًا‬\n      ‫وأمــا الضــرب فقــد ضربهــا مرتــن وقــد حضــر حكــم الــزوج وحكــم‬\n      ‫الزوجــة وحاولنــا يف اإلصــاح وتقريــب وجهــات النظــر لكــن أصــرت‬\n      ‫الزوجــة علــى عــدم الرجــوع وطلــب الطــاق وبعــد محــاوالت ونصــح أصــر‬\n      ‫الــزوج علــى عــدم طــاق زوجتــه وبعــد النظــر يف حالهمــا رأينــا صعوبــة‬\n      ‫اســتمرار احليــاة بينهمــا والــذي نــراه أن يفــرق بينهمــا بــدون عــوض هــذا‬\n      ‫مــا نــراه مناســب ًا واهلل أعلــم « مذيــل بتوقيــع حكــم الــزوج وحكــم‬\n      ‫الزوجــة ‪ ،‬وبعرضــه علــى املتداعيــن قــررت املدعــى عليهــا أنــه مريــض‬\n      ‫عقليــا حســب التقريــر املرفــق باملعاملــة وأيضــا ضعيــف جنســي ًا والقناعــة‬\n      ‫مبــا يف القــرار وذكــرت أنهــا مــن ذوات األقــراء ‪ ،‬وقــرر الــزوج عــدم‬\n      ‫القناعــة بــه حتــى تدفــع مبلــغ الذهــب الــذي أخذتــه والــذي حكــم بــه‬\n      ‫يف الصــك رقــم ‪ 33474111‬وتاريــخ ‪1433/123/20‬ه ـ هكــذا قــرر ‪.‬‬\n      ‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وملــا قــرر احلكمــان اللذان مت‬\n      ‫اختيارهمــا مــن قبــل الزوجــن مــن التفريــق بينهمــا بــدون عــوض ومــا مت‬\n      ‫مــن وعظهمــا وتوجيههمــا وإلصــرار كل منهمــا علــى رأيــه ولعمــوم قولــه‬\n      ‫تعالــى ‪( :‬وإن خفتــم شــقاق بينهمــا فابعثــوا حكم ـ ًا مــن أهلــه وحكم ـ ًا‬\n      ‫مــن أهلهــا إن يريــدا إصالحـ ًا يوفــق اهلل بينهمــا) وملــا رواه البخــاري عــن‬\n      ‫ابــن عبــاس رضــي اهلل عنهمــا قــال ‪ :‬جــاءت امــرأة ثابــت بــن قيــس بــن‬\n      ‫شــماس الــى النبــي صلــى اهلل عليــه وســلم فقالــت ‪ :‬يــا رســول اهلل مــا أنقم‬\n      ‫علــى ثابــت يف ديــن وال خلــق إال أنــي أخــاف الكفــر يف اإلســام فقــال‬\n      ‫رســول اهلل صلــى اهلل عليــه وســلم ‪( :‬أترديــن عليــه حديقتــه قالــت نعــم‬\n      ‫فــردت عليــه فأمــره ففارقهــا ) ولقولــه صلــى اهلل عليــه وســلم ‪( :‬ال ضــرر‬\n      ‫وال ضــرار) ‪ ،‬ونظــر ًا إلــى أن اســتمرار احليــاة الزوجيــة علــى هــذا الوضــع‬\n\n\n‫‪145‬‬\n\f‫أمــر ًا ال تتحقــق منــه مقاصــد النــكاح يف الشــريعة مــن املــودة والرحمــة‬\n‫والســكن وتربيــة األوالد والعفــة ‪ ،‬مــع مــا يف ذلــك مــن املضــار النفســية‬\n‫واالجتماعيــة واجلســدية علــى الزوجــن واألوالد‪ ،‬ولكــون مطالبــة الزوج‬\n‫بالذهــب محكــوم لــه بــه وال عالقــة لــه بعقــد الزوجيــة لــذا فقد حكمت‬\n‫بفســخ نــكاح املدعــى عليهــا مــن زوجهــا املدعــى بــدون عــوض وعليــه‬\n‫أفهمــت املدعــى عليهــا بــأن عليهــا العــدة الشــرعية وهــي ثــاث حيــض‬\n‫ـداء مــن اليــوم وال تتــزوج إال بعــد انتهــاء العــدة واكتســاب احلكــم‬      ‫إبتـ ً‬\n‫القطعيــة وبعــرض ذلــك علــى املتداعيــن قــررت املدعــى عليهــا القناعة به‬\n‫وقــرر املدعــي عــدم القناعــة وطلــب رفعــه إلــى محكمــة اإلســتئناف مــع‬\n‫الئحتــه االعتراضيــة فأجبتــه لطلبــه وأفهمتــه بــأن لــه اســتالم نســخة مــن‬\n‫احلكــم بعــد ثالثــة أيــام وأن لــه مهلــة ثالثــون يوم ـ ًا مــن تاريــخ االســتالم‬\n‫لتقــدمي الئحتــه االعتراضيــة وإال يســقط حقــه يف االعتــراض ويكتســب‬\n‫احلكــم القطعيــة حســب املــادة ‪ 178‬مــن نظــام املرافعــات الشــرعية‬\n‫ففهــم ذلــك وجــرى إفهــام املدعيــة بــأن ال تتــزوج حتــى يكتســب احلكــم‬\n‫القطعيــة ‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                  ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/1/28‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فقــد‬\n‫عــادت إلينــا املعاملــة مــن محكمــة االســتئناف بقرارهــا رقــم (‪)0000‬‬\n‫وتاريــخ ‪1434/5/22‬ه ـ الصــادر مــن دائــرة األحــوال الشــخصية الثالثــة‪.‬‬\n‫املتضمــن املوافقــة علــى احلكــم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n               ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/6/12‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة الثالثــة لألحــوال الشــخصية واألوقــاف‬\n\n\n                                                                                         ‫‪146‬‬\n\f      ‫والوصايــا والقصــار وبيــوت املــال مبحكمــة االســتئناف يف منطقــة‬\n      ‫االطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة رقــم‬\n      ‫(‪ )0000‬وتاريــخ ‪1434/4/27‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة‬\n      ‫الشــيخ (‪ )0000‬القاضــي باحملكمــة العامــة رقــم (‪ )0000‬وتاريــخ‬\n      ‫‪1434/1/28‬ه ـ ‪ ،‬املتضمــن دعــوى ضــد املــرأة يف املعاشــرة باملعــروف‪،‬‬\n      ‫وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة ‪ ،‬تقــررت‬\n      ‫املوافقــة علــى احلكــم ‪ ،‬مــع مالحظــة التنبيــه املرفــق ‪ ،‬واهلل املوفــق ‪.‬‬\n                       ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪147‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":140,"source_page_end":147,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"4568541e5567071dc7b5d46240cc3ff442a5734f46c644b08b9be98b3a36f8f9","normalized_text_hash":"73c88ecf5c347c8ae68271516410dd6205e5873141ad98f47ee7e1a7905705f1","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p140-3426340"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

